:root {
  --gold: #d8b06b;
  --gold-bright: #f0cd8a;
  --ink: #f3ead8;
  --ink-dim: #c7bca8;
  --panel: rgba(20, 24, 20, 0.72);
  --panel-edge: rgba(216, 176, 107, 0.28);
  --hp: #c4564a;
  --hp-bright: #e47a66;
  --mp: #4f8f9e;
  --mp-bright: #7cc3cf;
  --moss: #82a86e;
  --serif: "Palatino Linotype", "Book Antiqua", Palatino, "Iowan Old Style", Georgia, serif;
  --sans: "Segoe UI", system-ui, -apple-system, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  height: 100%;
  overflow: hidden;
  background: #10140f;
  color: var(--ink);
  font-family: var(--sans);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  cursor: crosshair;
  touch-action: none;
}

.hidden { display: none !important; }

/* ================= HUD ================= */
#hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  padding: max(14px, env(safe-area-inset-top)) max(16px, env(safe-area-inset-right)) max(14px, env(safe-area-inset-bottom)) max(16px, env(safe-area-inset-left));
}

.hud-left {
  position: absolute;
  top: max(16px, env(safe-area-inset-top));
  left: max(18px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  gap: 12px;
  width: min(406px, calc(100vw - 40px));
}

.panel {
  background: linear-gradient(160deg, rgba(31, 38, 30, 0.88), rgba(15, 19, 16, 0.82));
  border: 1px solid var(--panel-edge);
  border-radius: 14px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.32), inset 0 1px 0 rgba(255, 238, 196, 0.06);
  backdrop-filter: blur(7px);
  -webkit-backdrop-filter: blur(7px);
}

.vitals {
  display: flex;
  gap: 13px;
  padding: 11px 15px 12px 11px;
  align-items: center;
}

.portrait {
  width: 58px;
  height: 58px;
  flex: 0 0 auto;
  border-radius: 50%;
  box-shadow: 0 0 0 1px rgba(216, 176, 107, 0.5), 0 4px 14px rgba(0, 0, 0, 0.4);
  overflow: hidden;
  background: #1e332e;
}
.portrait svg { width: 100%; height: 100%; display: block; }

.bars { flex: 1; display: flex; flex-direction: column; gap: 8px; min-width: 0; }
.bar-row { display: flex; align-items: center; gap: 8px; }
.bar-icon {
  width: 17px;
  text-align: center;
  color: #e08373;
  font-size: 14px;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.6);
}
.bar-icon.mana { color: #82c3ce; font-size: 15px; }

.bar {
  position: relative;
  height: 19px;
  flex: 1;
  border-radius: 10px;
  background: rgba(0, 0, 0, 0.46);
  border: 1px solid rgba(255, 236, 200, 0.13);
  overflow: hidden;
  box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.5);
}
.bar .fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  border-radius: 9px;
  transition: width 0.16s ease-out;
}
.bar.health .fill {
  background: linear-gradient(180deg, var(--hp-bright), #9e3b34 70%);
  box-shadow: inset 0 1px 0 rgba(255, 210, 190, 0.55), 0 0 14px rgba(196, 86, 74, 0.35);
}
.bar.mana .fill {
  background: linear-gradient(180deg, var(--mp-bright), #2f6b78 70%);
  box-shadow: inset 0 1px 0 rgba(210, 250, 255, 0.45), 0 0 14px rgba(79, 143, 158, 0.35);
}
.bar-text {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10.5px;
  letter-spacing: 0.08em;
  font-weight: 600;
  color: #fff5e2;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9);
  font-variant-numeric: tabular-nums;
}

.quest {
  padding: 12px 16px 14px;
  border-left: 3px solid var(--gold);
  background: linear-gradient(120deg, rgba(35, 41, 31, 0.92), rgba(16, 20, 16, 0.8));
}
.quest-kicker {
  font-size: 9px;
  letter-spacing: 0.24em;
  color: var(--gold);
  opacity: 0.9;
  margin-bottom: 5px;
}
.quest-title {
  font-family: var(--serif);
  font-size: 19px;
  line-height: 1.15;
  color: #f7eeda;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.6);
}
.quest-objective {
  margin-top: 5px;
  font-size: 12px;
  line-height: 1.45;
  color: #cfc4ae;
}
.quest-objective b { color: var(--gold-bright); font-weight: 600; }

.hud-right {
  position: absolute;
  top: max(16px, env(safe-area-inset-top));
  right: max(18px, env(safe-area-inset-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.mini-wrap { padding: 8px 9px 9px; width: 218px; }
.mini-head {
  display: flex;
  justify-content: space-between;
  font-size: 8.5px;
  letter-spacing: 0.16em;
  color: var(--gold);
  padding: 1px 3px 6px;
}
#minimap {
  width: 200px;
  height: 150px;
  display: block;
  border-radius: 8px;
  border: 1px solid rgba(232, 205, 153, 0.14);
  background: #1b241c;
}
.essence-row {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 4px 1px;
  font-family: var(--serif);
  font-size: 17px;
  color: var(--gold-bright);
}
.essence-gem {
  width: 11px;
  height: 11px;
  background: linear-gradient(140deg, #ffd98f, #b7742f);
  transform: rotate(45deg);
  box-shadow: 0 0 9px rgba(255, 190, 100, 0.6);
  border-radius: 2px;
}
.essence-label {
  font-family: var(--sans);
  font-size: 9px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #9d9482;
}

.sys-buttons { display: flex; gap: 8px; pointer-events: auto; }
.icon-btn {
  width: 34px;
  height: 34px;
  border-radius: 9px;
  border: 1px solid rgba(216, 176, 107, 0.28);
  background: rgba(18, 22, 18, 0.78);
  color: #d7c7a6;
  font-size: 12px;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s, color 0.15s, transform 0.1s;
  backdrop-filter: blur(5px);
}
.icon-btn:hover { background: rgba(54, 62, 46, 0.92); color: #ffe6b0; }
.icon-btn:active { transform: scale(0.94); }
.icon-btn.muted { color: #8d7f6a; text-decoration: line-through; }

.boss-bar {
  position: absolute;
  top: max(20px, env(safe-area-inset-top));
  left: 50%;
  transform: translateX(-50%);
  width: min(520px, 54vw);
  text-align: center;
  animation: bossIn 0.4s ease-out;
}
@keyframes bossIn { from { opacity: 0; transform: translate(-50%, -10px); } to { opacity: 1; transform: translate(-50%, 0); } }
.boss-name {
  font-family: var(--serif);
  font-size: 13px;
  letter-spacing: 0.28em;
  color: #e9c58b;
  text-shadow: 0 2px 8px #000;
  margin-bottom: 5px;
}
.boss-track {
  height: 11px;
  border-radius: 6px;
  background: rgba(0, 0, 0, 0.62);
  border: 1px solid rgba(240, 200, 130, 0.32);
  overflow: hidden;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.4);
}
.boss-fill {
  height: 100%;
  width: 100%;
  background: linear-gradient(180deg, #e7a45c, #8f3a2e 65%, #5c2020);
  box-shadow: 0 0 16px rgba(226, 122, 66, 0.55);
  transition: width 0.2s ease;
}

.interact {
  position: absolute;
  left: 50%;
  bottom: max(112px, calc(env(safe-area-inset-bottom) + 96px));
  transform: translateX(-50%);
  background: rgba(16, 20, 16, 0.86);
  border: 1px solid rgba(216, 176, 107, 0.34);
  padding: 8px 14px 8px 9px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 12.5px;
  color: #eee2c9;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35);
  animation: promptIn 0.22s ease-out;
}
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 5px); } }
.interact .key {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 5px;
  background: linear-gradient(180deg, #e8c88d, #bb8e46);
  color: #2a2417;
  font-weight: 700;
  font-size: 11px;
  box-shadow: 0 1px 0 #f6e1b8 inset;
}

.toast {
  position: absolute;
  left: 50%;
  top: 74px;
  transform: translate(-50%, -8px);
  background: rgba(19, 24, 18, 0.9);
  border: 1px solid rgba(216, 176, 107, 0.3);
  border-radius: 999px;
  padding: 8px 20px;
  font-family: var(--serif);
  font-size: 14px;
  color: #f4e8cf;
  letter-spacing: 0.02em;
  opacity: 0;
  transition: opacity 0.3s, transform 0.3s;
  white-space: nowrap;
  max-width: 88vw;
  overflow: hidden;
  text-overflow: ellipsis;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.4);
  pointer-events: none;
}
.toast.show { opacity: 1; transform: translate(-50%, 0); }
.toast.gold { border-color: rgba(240, 205, 138, 0.6); color: #ffe6b4; }

.area-label {
  position: absolute;
  left: 50%;
  top: 33%;
  transform: translate(-50%, -50%);
  font-family: var(--serif);
  font-size: clamp(30px, 4.6vw, 58px);
  letter-spacing: 0.26em;
  color: #f1e2c2;
  text-transform: uppercase;
  text-shadow: 0 3px 22px rgba(0, 0, 0, 0.85), 0 0 60px rgba(255, 210, 130, 0.18);
  opacity: 0;
  transition: opacity 1.1s ease;
  pointer-events: none;
  text-align: center;
  white-space: nowrap;
}
.area-label small {
  display: block;
  font-family: var(--sans);
  font-size: 10px;
  letter-spacing: 0.5em;
  color: #d7b87d;
  margin-top: 10px;
}
.area-label.show { opacity: 0.95; }

.controls-hint {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: max(14px, env(safe-area-inset-bottom));
  display: flex;
  gap: 14px;
  flex-wrap: wrap;
  font-size: 10px;
  letter-spacing: 0.05em;
  color: rgba(236, 225, 203, 0.62);
  text-shadow: 0 1px 3px #000;
  max-width: 46vw;
}
.controls-hint b { color: rgba(246, 226, 184, 0.95); font-weight: 600; }

/* ================= TOUCH ================= */
.touch-ui { display: none; }
.joystick-active .joy-base { display: block; }
.joy-zone {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 46vw;
  height: 42vh;
  pointer-events: auto;
  touch-action: none;
}
.joy-base {
  display: none;
  position: fixed;
  width: 116px;
  height: 116px;
  margin-left: -58px;
  margin-top: -58px;
  border-radius: 50%;
  border: 1.5px solid rgba(240, 214, 160, 0.32);
  background: radial-gradient(circle at 50% 50%, rgba(28, 36, 28, 0.36), rgba(20, 26, 20, 0.14));
  box-shadow: 0 0 30px rgba(0, 0, 0, 0.2), inset 0 0 20px rgba(240, 214, 160, 0.05);
  pointer-events: none;
}
.joy-knob {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 52px;
  height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  background: radial-gradient(circle at 38% 32%, #e6d3a8, #9c7c48 62%, #6f552e);
  border: 1px solid rgba(255, 238, 200, 0.5);
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.4), inset 0 1px 3px rgba(255, 255, 255, 0.4);
}
.action-buttons {
  position: absolute;
  right: max(20px, env(safe-area-inset-right));
  bottom: max(26px, calc(env(safe-area-inset-bottom) + 16px));
  display: flex;
  align-items: flex-end;
  gap: 14px;
  pointer-events: auto;
}
.round-btn {
  width: 84px;
