// ------------------------------------------------------- mountain silhouettes
buildMountainRidges() {
  const rng = mulberry32(0x77aa33);
  const makeTop = (base, peakMin, peakMax, invert) => {
    const pts = [];
    const n = 16;
    for (let i = 0; i <= n; i++) {
      const x = -260 + (WORLD_W + 520) * (i / n);
      const wave = Math.sin(i * 1.7) * 0.5 + 0.5;
      const peak = peakMin + rng() * (peakMax - peakMin) * (0.4 + wave * 0.6);
      pts.push([x, invert ? base - peak : peak]);
    }
    return pts;
  };
  this.ridges = {
    top: makeTop(560, 160, 400, true),
    bottom: makeTop(WORLD_H - 560, 160, 400, false),
    left: makeTop(560, 160, 400, true),
    right: makeTop(WORLD_W - 560, 160, 400, false)
  };
  // Turn the horizontal point lists into usable side ridges.
  const mirror = (pts, side) => pts.map(([a, b]) => side === 'left' ? [b, a] : [b, a]);
  this.ridges.left = mirror(this.ridges.left, 'left');
  this.ridges.right = mirror(this.ridges.right, 'right');
  this.ridgeSeeds = [];
  for (let i = 0; i < 40; i++) this.ridgeSeeds.push(rng());
}

