import { TAU, hash2, clamp, mulberry32, roundedRect } from './util.js';
import {
  WORLD_W, WORLD_H, RIVER, RIVER_W, POND, BRIDGE, CAVE, BIOME
} from './world-data.js';

// ---------------------------------------------------------------- ground layer
export function drawGround(world, ctx, view, time, quality = 1) {
  const S = world.terrainScale;
  const sx = clamp(view.x * S, 0, world.terrainW);
  const sy = clamp(view.y * S, 0, world.terrainH);
  const sw = clamp(view.w * S + 1, 1, world.terrainW - sx);
  const sh = clamp(view.h * S + 1, 1, world.terrainH - sy);
  ctx.imageSmoothingEnabled = true;
  ctx.drawImage(world.terrain, sx, sy, sw, sh, view.x, view.y, view.w, view.h);

  drawWaterShimmer(ctx, view, time);

  // Crisp little details, one or two per visible biome cell.
  const cell = 56;
  const x0 = Math.floor(view.x / cell) - 1;
  const x1 = Math.floor((view.x + view.w) / cell) + 1;
  const y0 = Math.floor(view.y / cell) - 1;
  const y1 = Math.floor((view.y + view.h) / cell) + 1;
  const density = quality > 0.75 ? 1 : 0.55;

  for (let gy = y0; gy <= y1; gy++) {
    for (let gx = x0; gx <= x1; gx++) {
      const h = hash2(gx, gy, 77);
      if (h > 0.62 * density) continue;
      const x = (gx + 0.15 + hash2(gx, gy, 5) * 0.7) * cell;
      const y = (gy + 0.15 + hash2(gx, gy, 9) * 0.7) * cell;
      const b = world.biomeAt(x, y);
      if (b === BIOME.water) continue;
      const h2 = hash2(gx, gy, 31);
      const sway = Math.sin(time * 1.25 + h2 * 14) * 1.2;
      ctx.lineCap = 'round';

      if (b === BIOME.dirt) {
        if (h2 > 0.5) {
          ctx.fillStyle = h2 > 0.78 ? 'rgba(90,72,46,0.28)' : 'rgba(220,192,138,0.22)';
          ctx.beginPath();
          ctx.ellipse(x, y, 1.6 + h2 * 2.4, 1 + h2 * 1.4, h2 * 3, 0, TAU);
          ctx.fill();
        } else {
          ctx.strokeStyle = 'rgba(143,120,78,0.34)';
          ctx.lineWidth = 1.1;
          ctx.beginPath();
          ctx.moveTo(x - 4, y + 2);
          ctx.lineTo(x + sway, y - 4);
          ctx.stroke();
        }
      } else if (b === BIOME.rock) {
        ctx.fillStyle = 'rgba(92,92,82,0.28)';
        ctx.beginPath();
        ctx.ellipse(x, y, 2 + h2 * 3, 1.4 + h2 * 2, h2 * 2, 0, TAU);
        ctx.fill();
      } else if (b === BIOME.forest) {
        const shade = h2 > 0.5 ? 'rgba(44,69,36,0.42)' : 'rgba(106,135,74,0.34)';
        ctx.strokeStyle = shade;
        ctx.lineWidth = 1.35;
        ctx.beginPath();
        ctx.moveTo(x - 2, y + 3);
        ctx.quadraticCurveTo(x + sway, y - 2, x + sway * 0.6, y - 7);
        ctx.moveTo(x + 3, y + 3);
        ctx.quadraticCurveTo(x + 5 + sway, y - 1, x + 4 + sway * 0.6, y - 5);
        ctx.stroke();
        if (h2 > 0.82) {
          ctx.fillStyle = 'rgba(198,180,110,0.35)';
          ctx.beginPath();
          ctx.arc(x + 3, y - 3, 1.6, 0, TAU);
          ctx.fill();
        }
      } else {
        const tone = h2 > 0.6 ? 'rgba(128,154,89,0.46)' : 'rgba(72,99,52,0.38)';
        ctx.strokeStyle = tone;
        ctx.lineWidth = 1.15;
        ctx.beginPath();
        ctx.moveTo(x - 2.5, y + 4);
        ctx.quadraticCurveTo(x - 3 + sway, y, x - 3.5 + sway, y - 6);
        ctx.moveTo(x + 1, y + 4);
        ctx.quadraticCurveTo(x + 1 + sway * 0.7, y - 1, x + sway * 0.5, y - 8);
        ctx.moveTo(x + 4, y + 4);
        ctx.quadraticCurveTo(x + 5 + sway, y + 1, x + 5, y - 4);
        ctx.stroke();
        if (h2 > 0.92) {
          ctx.fillStyle = h2 > 0.96 ? 'rgba(235,224,166,0.75)' : 'rgba(212,190,220,0.6)';
          ctx.beginPath();
          ctx.arc(x + 4.5, y - 6, 2.1, 0, TAU);
          ctx.fill();
          ctx.fillStyle = 'rgba(255,255,255,0.45)';
          ctx.beginPath();
          ctx.arc(x + 4.2, y - 6.5, 0.8, 0, TAU);
          ctx.fill();
        }
      }
    }
  }
}

function drawWaterShimmer(ctx, view, time) {
  const visible = (x, y) => x > view.x - 80 && x < view.x + view.w + 80 && y > view.y - 80 && y < view.y + view.h + 80;
  ctx.lineCap = 'round';
  // River glints.
  const step = 0.055;
  for (let i = 0; i < RIVER.length - 1; i++) {
    const a = RIVER[i];
    const b = RIVER[i + 1];
    const segLen = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const count = Math.max(1, Math.floor(segLen / 110));
    for (let j = 0; j < count; j++) {
      const t = (j + 0.5) / count;
      const x = a[0] + (b[0] - a[0]) * t;
      const y = a[1] + (b[1] - a[1]) * t;
      if (!visible(x, y)) continue;
      const h = hash2(i, j, 3);
      const dx = (b[0] - a[0]) / segLen;
      const dy = (b[1] - a[1]) / segLen;
      const nx = -dy;
      const ny = dx;
      const off = (h - 0.5) * RIVER_W * 0.5;
      const ph = time * 0.7 + h * 9;
      const len = 14 + h * 26;
      const alpha = 0.1 + 0.08 * (0.5 + 0.5 * Math.sin(ph));
      ctx.strokeStyle = `rgba(176,222,220,${alpha.toFixed(3)})`;
      ctx.lineWidth = 2.2;
      ctx.beginPath();
      ctx.moveTo(x + nx * off - dx * len, y + ny * off - dy * len);
      ctx.quadraticCurveTo(x + nx * (off + 5), y + ny * (off + 5), x + nx * off + dx * len, y + ny * off + dy * len);
      ctx.stroke();
    }
  }
  // Pond rings.
  if (visible(POND.x, POND.y)) {
    for (let k = 0; k < 3; k++) {
      const phase = (time * 0.11 + k * 0.33) % 1;
      const r = 40 + phase * 240;
      ctx.strokeStyle = `rgba(173,220,218,${(0.1 * (1 - phase)).toFixed(3)})`;
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.ellipse(POND.x - 50, POND.y - 30, r, r * 0.62, 0, 0, TAU);
      ctx.stroke();
    }
    // Lily glints.
    for (let i = 0; i < 7; i++) {
      const a = i * 2.399;
      const x = POND.x + Math.cos(a) * 140;
      const y = POND.y + Math.sin(a) * 84;
      ctx.fillStyle = 'rgba(90,128,72,0.55)';
      ctx.beginPath();
      ctx.ellipse(x, y, 13, 8, a, 0, TAU);
      ctx.fill();
      ctx.fillStyle = 'rgba(238,232,203,0.6)';
      ctx.beginPath();
      ctx.arc(x + 3, y - 2, 2.4, 0, TAU);
      ctx.fill();
    }
  }
}

// ------------------------------------------------------------------- mountains
export function drawMountains(world, ctx, view, time) {
  const near = (x, y, pad) => x < view.x + view.w + pad && x > view.x - pad && y < view.y + view.h + pad && y > view.y - pad;
  if (view.y < 900) {
    drawBand(ctx, WORLD_W, 560, 11, time, 'top');
  }
  if (view.y + view.h > WORLD_H - 900) {
    ctx.save();
    ctx.transform(1, 0, 0, -1, 0, WORLD_H);
    drawBand(ctx, WORLD_W, 560, 27, time, 'bottom');
    ctx.restore();
  }
  if (view.x < 900) {
    ctx.save();
    ctx.transform(0, 1, 1, 0, 0, 0);
    drawBand(ctx, WORLD_H, 560, 43, time, 'left');
    ctx.restore();
  }
  if (view.x + view.w > WORLD_W - 900) {
    ctx.save();
    ctx.transform(0, 1, -1, 0, WORLD_W, 0);
    drawBand(ctx, WORLD_H, 560, 61, time, 'right');
    ctx.restore();
  }
}

function drawBand(ctx, length, base, seed, time, side) {
  const rng = mulberry32(seed * 7919 + 13);
  const x0 = -420;
  const x1 = length + 420;
  // Body of the range.
  const g = ctx.createLinearGradient(0, -400, 0, base + 30);
  g.addColorStop(0, '#414a4b');
  g.addColorStop(0.38, '#5a605f');
  g.addColorStop(0.82, '#747770');
  g.addColorStop(1, '#62665f');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.moveTo(x0, base);
  ctx.lineTo(x0, -420);
  ctx.lineTo(x1, -420);
  ctx.lineTo(x1, base);
  ctx.closePath();
  ctx.fill();

  // Faceted peak shapes, with snow.
  const count = Math.ceil((x1 - x0) / 250);
  for (let i = 0; i < count; i++) {
    const x = x0 + (i + 0.5) * ((x1 - x0) / count) + (rng() - 0.5) * 110;
    const w = 130 + rng() * 200;
    const h = 110 + rng() * 300;
    const apexY = base - h;
    if (apexY < -380) continue;
    const dark = rng() > 0.5;
    ctx.fillStyle = dark ? 'rgba(84,91,88,0.55)' : 'rgba(125,128,118,0.45)';
    ctx.beginPath();
    ctx.moveTo(x - w * 0.5, base + 10);
    ctx.lineTo(x, apexY);
    ctx.lineTo(x + w * 0.5, base + 10);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(48,54,53,0.36)';
    ctx.lineWidth = 2.4;
    ctx.beginPath();
    ctx.moveTo(x, apexY + 4);
    ctx.lineTo(x + (rng() - 0.5) * 40, base + 10);
    ctx.stroke();
    if (h > 260) {
      ctx.fillStyle = 'rgba(232,237,232,0.82)';
      ctx.beginPath();
      ctx.moveTo(x - 3, apexY + 2);
      ctx.lineTo(x - w * 0.16, apexY + 34 + rng() * 16);
      ctx.lineTo(x - w * 0.02, apexY + 22);
      ctx.lineTo(x + w * 0.09, apexY + 42);
      ctx.lineTo(x + w * 0.18, apexY + 30);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,0.35)';
      ctx.beginPath();
      ctx.moveTo(x - 1, apexY + 4);
      ctx.lineTo(x - w * 0.06, apexY + 20);
      ctx.lineTo(x + w * 0.04, apexY + 24);
      ctx.closePath();
      ctx.fill();
    }
  }

  // Rock striations.
  for (let i = 0; i < 26; i++) {
    const x = x0 + rng() * (x1 - x0);
    const y = base - rng() * 430;
    ctx.strokeStyle = `rgba(43,50,49,${0.1 + rng() * 0.2})`;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + 18 + rng() * 42, y - 7 - rng() * 18);
    ctx.stroke();
  }

  // Jagged talus edge spilling into the valley.
  ctx.fillStyle = '#5d615a';
  ctx.beginPath();
  ctx.moveTo(x0, base - 26);
  let bx = x0;
  while (bx < x1) {
    const w = 48 + rng() * 120;
    const d = 6 + rng() * 30;
    ctx.lineTo(bx + w * 0.45, base - 26 + d);
    ctx.lineTo(bx + w, base - 20);
    bx += w;
  }
  ctx.lineTo(x1, base + 8);
  ctx.lineTo(x0, base + 8);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = 'rgba(35,42,40,0.5)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(x0, base - 22);
  bx = x0;
  while (bx < x1) {
    const w = 48 + rng() * 120;
    ctx.lineTo(bx + w * 0.45, base - 22 + (rng() * 24));
    ctx.lineTo(bx + w, base - 18);
    bx += w;
  }
  ctx.stroke();

  // A handful of drifting mist bands at the foot.
  for (let i = 0; i < 5; i++) {
    const y = base - 30 - rng() * 80;
    const x = x0 + rng() * (x1 - x0);
    const w = 260 + rng() * 420;
    ctx.fillStyle = `rgba(207,218,214,${0.035 + rng() * 0.04})`;
    ctx.beginPath();
    ctx.ellipse(x + Math.sin(time * 0.04 + i) * 30, y, w * 0.5, 26 + rng() * 18, 0, 0, TAU);
    ctx.fill();
  }
}

// ---------------------------------------------------------------------- decals
export function drawDecals(world, ctx, view, time) {
  for (const d of world.decals) {
    switch (d.kind) {
      case 'field': drawField(ctx, d, time); break;
      case 'bridge': drawBridge(ctx, d); break;
      case 'dock': drawDock(ctx, d); break;
      case 'cave': drawCave(ctx, d, time); break;
      default: break;
    }
  }
}

function drawField(ctx, d, time) {
  ctx.save();
  roundedRect(ctx, d.x, d.y, d.w, d.h, 20);
  ctx.fillStyle = '#6d5438';
  ctx.fill();
  ctx.strokeStyle = 'rgba(58,43,28,0.55)';
  ctx.lineWidth = 5;
  ctx.stroke();
  const rows = 15;
  for (let i = 0; i < rows; i++) {
    const y = d.y + 18 + i * ((d.h - 34) / rows);
    ctx.strokeStyle = 'rgba(51,37,24,0.5)';
    ctx.lineWidth = 7;
    ctx.beginPath();
    ctx.moveTo(d.x + 16, y);
    ctx.lineTo(d.x + d.w - 16, y);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(168,139,92,0.18)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(d.x + 16, y + 4);
    ctx.lineTo(d.x + d.w - 16, y + 4);
    ctx.stroke();
    for (let j = 0; j < 18; j++) {
      const x = d.x + 22 + j * ((d.w - 44) / 18) + Math.sin(i * 2 + j) * 2;
      const h = hash2(i, j, 9);
      const sway = Math.sin(time * 1.1 + i + j * 0.7) * 1.3;
      ctx.strokeStyle = h > 0.5 ? 'rgba(114,145,68,0.85)' : 'rgba(88,120,52,0.85)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x, y + 2);
      ctx.quadraticCurveTo(x + sway, y - 7, x + sway * 1.4, y - 13);
      ctx.stroke();
      if (h > 0.9) {
        ctx.fillStyle = h > 0.95 ? '#d98a3c' : '#c9b34e';
        ctx.beginPath();
        ctx.arc(x + sway * 1.4, y - 14, 3.4, 0, TAU);
        ctx.fill();
      }
    }
  }
  ctx.restore();
}

function drawBridge(ctx, d) {
  ctx.save();
  ctx.fillStyle = 'rgba(20,28,24,0.28)';
  roundedRect(ctx, d.x + 10, d.y + 16, d.w, d.h, 12);
  ctx.fill();
  roundedRect(ctx, d.x, d.y, d.w, d.h, 10);
  ctx.fillStyle = '#8a6b45';
  ctx.fill();
  const planks = 22;
  for (let i = 0; i < planks; i++) {
    const y = d.y + 6 + i * ((d.h - 12) / planks);
    ctx.fillStyle = i % 2 === 0 ? 'rgba(191,159,108,0.55)' : 'rgba(88,66,43,0.4)';
    ctx.fillRect(d.x + 5, y, d.w - 10, (d.h - 12) / planks - 2);
  }
  ctx.strokeStyle = '#4f3b27';
  ctx.lineWidth = 6;
  ctx.beginPath();
  ctx.moveTo(d.x + 8, d.y + 9);
  ctx.lineTo(d.x + d.w - 8, d.y + 9);
  ctx.moveTo(d.x + 8, d.y + d.h - 9);
  ctx.lineTo(d.x + d.w - 8, d.y + d.h - 9);
  ctx.stroke();
  for (let i = 0; i < 7; i++) {
    const x = d.x + 12 + i * ((d.w - 24) / 6);
    ctx.fillStyle = '#4a3724';
    ctx.fillRect(x, d.y + 2, 7, 16);
    ctx.fillRect(x, d.y + d.h - 18, 7, 16);
  }
  ctx.restore();
}

function drawDock(ctx, d) {
  ctx.save();
  ctx.fillStyle = 'rgba(20,27,24,0.25)';
  roundedRect(ctx, d.x + 8, d.y + 12, d.w, d.h, 6);
  ctx.fill();
  roundedRect(ctx, d.x, d.y, d.w, d.h, 4);
  ctx.fillStyle = '#8a6c48';
  ctx.fill();
  for (let i = 0; i < 16; i++) {
    const y = d.y + 4 + i * ((d.h - 8) / 16);
    ctx.fillStyle = i % 2 ? 'rgba(190,154,101,0.4)' : 'rgba(95,72,46,0.32)';
    ctx.fillRect(d.x + 4, y, d.w - 8, (d.h - 8) / 16 - 2);
  }
  ctx.fillStyle = '#4c3823';
  for (const [x, y] of [[d.x + 2, d.y + 8], [d.x + d.w - 8, d.y + 8], [d.x + 2, d.y + d.h - 10], [d.x + d.w - 8, d.y + d.h - 10]]) {
    ctx.fillRect(x, y, 7, 11);
  }
  ctx.restore();
}

function drawCave(ctx, d, time) {
  const x = d.x;
  const y = d.y;
  ctx.save();

  // Deep stone shelf.
  ctx.fillStyle = 'rgba(56,58,53,0.5)';
  ctx.beginPath();
  ctx.ellipse(x, y + 190, 520, 280, 0, 0, TAU);
  ctx.fill();

  // Main massif.
  const grd = ctx.createLinearGradient(x, y - 460, x, y + 290);
  grd.addColorStop(0, '#555b58');
  grd.addColorStop(0.52, '#73766e');
  grd.addColorStop(1, '#575b55');
  ctx.fillStyle = grd;
  ctx.beginPath();
  ctx.moveTo(x - 600, y + 320);
  ctx.lineTo(x - 560, y - 40);
  ctx.lineTo(x - 430, y - 230);
  ctx.lineTo(x - 300, y - 320);
  ctx.lineTo(x - 150, y - 390);
  ctx.lineTo(x - 30, y - 330);
  ctx.lineTo(x + 60, y - 420);
  ctx.lineTo(x + 190, y - 350);
  ctx.lineTo(x + 330, y - 380);
  ctx.lineTo(x + 470, y - 280);
  ctx.lineTo(x + 560, y - 90);
  ctx.lineTo(x + 600, y + 320);
  ctx.closePath();
  ctx.fill();

  // Rock faces.
  ctx.fillStyle = 'rgba(128,128,116,0.42)';
  ctx.beginPath();
  ctx.moveTo(x + 20, y - 400);
  ctx.lineTo(x + 300, y - 360);
  ctx.lineTo(x + 430, y - 120);
  ctx.lineTo(x + 210, y - 190);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(58,64,61,0.42)';
  ctx.beginPath();
  ctx.moveTo(x - 560, y + 60);
  ctx.lineTo(x - 370, y - 210);
  ctx.lineTo(x - 170, y - 260);
  ctx.lineTo(x - 280, y + 120);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(100,104,94,0.35)';
  ctx.beginPath();
  ctx.moveTo(x - 90, y - 340);
  ctx.lineTo(x + 130, y - 360);
  ctx.lineTo(x + 60, y - 120);
  ctx.lineTo(x - 200, y - 150);
  ctx.closePath();
  ctx.fill();

  // A shelf of cracks and ledges.
  ctx.strokeStyle = 'rgba(42,49,46,0.5)';
  ctx.lineWidth = 4;
  for (const [x1, y1, x2, y2] of [
    [x - 470, y - 40, x - 330, y - 120],
    [x + 350, y - 60, x + 470, y - 140],
    [x - 140, y - 330, x - 60, y - 190],
    [x + 140, y - 300, x + 210, y - 170],
    [x - 410, y + 100, x - 260, y + 60]
  ]) {
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo((x1 + x2) / 2 + 18, (y1 + y2) / 2);
    ctx.lineTo(x2, y2);
    ctx.stroke();
  }

  // The mouth.
  ctx.beginPath();
  ctx.moveTo(x - 138, y + 170);
  ctx.lineTo(x - 138, y - 35);
  ctx.bezierCurveTo(x - 138, y - 150, x - 60, y - 170, x, y - 174);
  ctx.bezierCurveTo(x + 62, y - 170, x + 138, y - 150, x + 138, y - 35);
  ctx.lineTo(x + 138, y + 170);
  ctx.closePath();
  const voidg = ctx.createRadialGradient(x, y + 20, 20, x, y - 20, 300);
  voidg.addColorStop(0, '#04070a');
  voidg.addColorStop(0.55, '#070d12');
  voidg.addColorStop(1, '#101a1e');
  ctx.fillStyle = voidg;
  ctx.fill();

  // Wet rim light around the arch.
  ctx.strokeStyle = 'rgba(130,171,178,0.28)';
  ctx.lineWidth = 5;
  ctx.stroke();

  // Glow far inside.
  const glow = ctx.createRadialGradient(x, y + 120, 0, x, y + 120, 120);
  glow.addColorStop(0, `rgba(70,148,168,${0.25 + Math.sin(time * 1.3) * 0.05})`);
  glow.addColorStop(1, 'rgba(70,148,168,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.ellipse(x, y + 120, 120, 70, 0, 0, TAU);
  ctx.fill();

  // Rune carvings flanking the mouth.
  ctx.strokeStyle = 'rgba(116,205,221,0.5)';
  ctx.lineWidth = 3;
  ctx.lineCap = 'round';
  const runes = [[-205, 10], [205, 20], [-240, -80], [245, -70]];
  for (let i = 0; i < runes.length; i++) {
    const [rx, ry] = runes[i];
    const pulse = 0.4 + 0.3 * Math.sin(time * 1.6 + i);
    ctx.globalAlpha = pulse;
    ctx.beginPath();
    ctx.moveTo(x + rx - 12, y + ry + 14);
    ctx.lineTo(x + rx, y + ry - 12);
    ctx.lineTo(x + rx + 12, y + ry + 8);
    ctx.lineTo(x + rx - 4, y + ry + 4);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // Stepping stones into the dark.
  ctx.fillStyle = 'rgba(99,102,92,0.5)';
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.ellipse(x - 40 + i * 26, y + 150 + i * 28, 28 - i * 2, 13 - i, 0.2, 0, TAU);
    ctx.fill();
  }

  ctx.restore();
}

import { TAU, hash2, roundedRect, lerp } from './util.js';

export function drawObject(ctx, o, time) {
  switch (o.kind) {
    case 'tree': drawTree(ctx, o, time); break;
    case 'bush': drawBush(ctx, o, time); break;
    case 'rock': drawRock(ctx, o); break;
    case 'boulder': drawBoulder(ctx, o); break;
    case 'crystal': drawCrystal(ctx, o, time); break;
    case 'deadtree': drawDeadTree(ctx, o); break;
    case 'house': drawHouse(ctx, o); break;
    case 'well': drawWell(ctx, o, time); break;
    case 'shrine': drawShrine(ctx, o, time); break;
    case 'campfire': drawCampfire(ctx, o, time); break;
    case 'stall': drawStall(ctx, o); break;
    case 'fence': drawFence(ctx, o); break;
    case 'lantern': drawLantern(ctx, o, time); break;
    case 'crate': drawCrate(ctx, o); break;
    case 'barrel': drawBarrel(ctx, o); break;
    case 'hay': drawHay(ctx, o); break;
    case 'bench': drawBench(ctx, o); break;
    case 'cart': drawCart(ctx, o); break;
    case 'sign': drawSign(ctx, o); break;
    case 'reed': drawReed(ctx, o, time); break;
    case 'lily': drawLily(ctx, o, time); break;
    case 'log': drawLog(ctx, o); break;
    case 'stump': drawStump(ctx, o); break;
    case 'fern': drawFern(ctx, o, time); break;
    case 'mushroom': drawMushroom(ctx, o); break;
    case 'flowers': drawFlowers(ctx, o, time); break;
    default: break;
  }
}

function shadow(ctx, x, y, rx, ry, alpha = 0.24, offset = 5) {
  ctx.fillStyle = `rgba(24,34,22,${alpha})`;
  ctx.beginPath();
  ctx.ellipse(x + offset * 0.6, y + offset, rx, ry, 0, 0, TAU);
  ctx.fill();
}

// ---------------------------------------------------------------------- flora
function drawTree(ctx, o, time) {
  const s = o.s;
  const sway = Math.sin(time * o.sway + o.seed) * 2.2 + Math.sin(time * 0.43 + o.seed * 2) * 0.8;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 0, 0, 30 * s, 9.5 * s, 0.22, 3);

  if (o.type === 'pine') {
    ctx.fillStyle = '#58412d';
    ctx.fillRect(-4 * s, -34 * s, 8 * s, 36 * s);
    ctx.fillStyle = '#6a4e35';
    ctx.fillRect(-4 * s, -34 * s, 3 * s, 36 * s);
    const layers = [
      [-16 * s, 0, 32 * s, 32 * s],
      [-12 * s, -30 * s, 25 * s, 26 * s],
      [-7 * s, -56 * s, 17 * s, 22 * s]
    ];
    for (let i = 0; i < layers.length; i++) {
      const [bx, by, bw, bh] = layers[i];
      const lift = -78 * s - i * 4;
      const peak = by + lift;
      ctx.fillStyle = o.tones[i] || o.tones[2];
      ctx.beginPath();
      ctx.moveTo(bx - sway * (i * 0.25), by);
      ctx.lineTo(sway * (1 + i * 0.2), peak);
      ctx.lineTo(bx + bw, by);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(30,52,28,0.32)';
      ctx.beginPath();
      ctx.moveTo(bx + bw * 0.5, by);
      ctx.lineTo(sway * (1 + i * 0.2), peak);
      ctx.lineTo(bx + bw, by);
      ctx.closePath();
      ctx.fill();
      ctx.fillStyle = 'rgba(168,190,124,0.22)';
      ctx.beginPath();
      ctx.moveTo(bx + bw * 0.12, by - 1);
      ctx.lineTo(sway * (1 + i * 0.2) - 3, peak + 8 * s);
      ctx.lineTo(bx + bw * 0.32, by - 1);
      ctx.closePath();
      ctx.fill();
    }
  } else if (o.type === 'birch') {
    ctx.fillStyle = '#d9d6c4';
    ctx.beginPath();
    ctx.moveTo(-4 * s, 0);
    ctx.lineTo(-3 * s, -46 * s);
    ctx.lineTo(3 * s, -46 * s);
    ctx.lineTo(4 * s, 0);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = '#4b443a';
    for (let i = 0; i < 4; i++) ctx.fillRect(-3 * s, -37 * s + i * 8 * s, 6 * s, 1.5 * s);
    const c = o.tones;
    ctx.fillStyle = c[0];
    ctx.beginPath();
    ctx.ellipse(sway * 0.6, -62 * s, 27 * s, 24 * s, 0.1, 0, TAU);
    ctx.fill();
    ctx.fillStyle = c[1];
    ctx.beginPath();
    ctx.ellipse(sway * 0.6 - 8 * s, -68 * s, 20 * s, 17 * s, -0.2, 0, TAU);
    ctx.fill();
    ctx.fillStyle = c[2];
    ctx.beginPath();
    ctx.ellipse(sway * 0.5 - 13 * s, -73 * s, 11 * s, 9 * s, -0.4, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,246,200,0.16)';
    ctx.beginPath();
    ctx.ellipse(sway * 0.5 - 15 * s, -77 * s, 7 * s, 5 * s, -0.4, 0, TAU);
    ctx.fill();
  } else {
    // Oak.
    ctx.fillStyle = '#5a4330';
    ctx.beginPath();
    ctx.moveTo(-6 * s, 0);
    ctx.lineTo(-4 * s, -44 * s);
    ctx.lineTo(4 * s, -48 * s);
    ctx.lineTo(6 * s, 0);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = '#4a3626';
    ctx.lineWidth = 2.6 * s;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(0, -36 * s);
    ctx.lineTo(-12 * s, -52 * s);
    ctx.moveTo(1, -40 * s);
    ctx.lineTo(13 * s, -56 * s);
    ctx.stroke();
    const c = o.tones;
    const blobs = [
      [-20, -68, 23], [17, -72, 24], [-3, -86, 27], [-25, -88, 17], [24, -92, 16]
    ];
    for (let i = 0; i < blobs.length; i++) {
      const [bx, by, br] = blobs[i];
      ctx.fillStyle = c[i % 2];
      ctx.beginPath();
      ctx.arc(bx * s + sway * (0.6 + i * 0.1), by * s, br * s, 0, TAU);
      ctx.fill();
    }
    ctx.fillStyle = c[2];
    ctx.beginPath();
    ctx.arc(-9 * s + sway * 0.8, -96 * s, 17 * s, 0, TAU);
    ctx.arc(13 * s + sway * 0.8, -88 * s, 13 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(255,240,170,0.13)';
    ctx.beginPath();
    ctx.arc(-12 * s + sway, -100 * s, 9 * s, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawBush(ctx, o, time) {
  const s = o.s;
  const sway = Math.sin(time * 0.9 + o.seed) * 1.2;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 0, 0, 20 * s, 6 * s, 0.18, 2);
  const c = o.tones;
  ctx.fillStyle = c[0];
  ctx.beginPath();
  ctx.ellipse(-9 * s + sway, -10 * s, 13 * s, 11 * s, -0.2, 0, TAU);
  ctx.ellipse(9 * s + sway, -11 * s, 14 * s, 12 * s, 0.2, 0, TAU);
  ctx.ellipse(sway, -17 * s, 15 * s, 13 * s, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = c[1];
  ctx.beginPath();
  ctx.ellipse(-4 * s + sway, -19 * s, 9 * s, 8 * s, -0.3, 0, TAU);
  ctx.ellipse(9 * s + sway, -16 * s, 7 * s, 6 * s, 0.3, 0, TAU);
  ctx.fill();
  if (o.berries) {
    ctx.fillStyle = '#a94238';
    for (let i = 0; i < 5; i++) {
      const a = i * 1.7 + o.seed;
      ctx.beginPath();
      ctx.arc(Math.cos(a) * 10 * s + sway, -14 * s + Math.sin(a) * 7 * s, 1.9 * s, 0, TAU);
      ctx.fill();
    }
  }
  ctx.restore();
}

function drawRock(ctx, o) {
  const s = o.s;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 0, 1, 26 * s, 8 * s, 0.2, 3);
  ctx.save();
  ctx.scale(s, s);
  ctx.fillStyle = o.tones[2];
  ctx.beginPath();
  o.pts.forEach(([px, py], i) => i ? ctx.lineTo(px, py) : ctx.moveTo(px, py));
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = o.tones[0];
  ctx.beginPath();
  o.pts.forEach(([px, py], i) => i ? ctx.lineTo(px * 0.8, py * 0.8 - 3) : ctx.moveTo(px * 0.8, py * 0.8 - 3));
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = o.tones[1];
  ctx.beginPath();
  ctx.moveTo(o.pts[0][0] * 0.45, o.pts[0][1] * 0.45 - 6);
  ctx.lineTo(o.pts[2][0] * 0.6, o.pts[2][1] * 0.6 - 8);
  ctx.lineTo(o.pts[3][0] * 0.55, o.pts[3][1] * 0.55 - 4);
  ctx.closePath();
  ctx.fill();
  ctx.restore();
  ctx.restore();
}

function drawBoulder(ctx, o) {
  const s = o.s;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 2, 6, 58 * s, 20 * s, 0.28, 6);
  ctx.save();
  ctx.scale(s, s);
  const pts = [];
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * TAU;
    const r = 46 + hash2(i, o.seed | 0, 7) * 16;
    pts.push([Math.cos(a) * r, Math.sin(a) * r * 0.7]);
  }
  ctx.fillStyle = '#62665d';
  ctx.beginPath();
  pts.forEach(([px, py], i) => i ? ctx.lineTo(px, py) : ctx.moveTo(px, py));
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#7d806f';
  ctx.beginPath();
  pts.forEach(([px, py], i) => i ? ctx.lineTo(px * 0.72, py * 0.72 - 10) : ctx.moveTo(px * 0.72, py * 0.72 - 10));
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#8f9182';
  ctx.beginPath();
  ctx.moveTo(-22, -22);
  ctx.lineTo(4, -30);
  ctx.lineTo(26, -12);
  ctx.lineTo(2, -8);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(92,110,64,0.45)';
  ctx.beginPath();
  ctx.ellipse(-18, 8, 18, 7, 0.2, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(42,47,43,0.5)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(6, -2);
  ctx.lineTo(14, 12);
  ctx.lineTo(4, 20);
  ctx.stroke();
  ctx.restore();
  ctx.restore();
}

function drawCrystal(ctx, o, time) {
  const s = o.s;
  const pulse = 0.75 + Math.sin(time * 1.7 + o.seed) * 0.25;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 0, 0, 16 * s, 5 * s, 0.16, 2);
  const glow = ctx.createRadialGradient(0, -18 * s, 2, 0, -18 * s, 64 * s);
  glow.addColorStop(0, `rgba(122,218,238,${0.28 * pulse})`);
  glow.addColorStop(1, 'rgba(122,218,238,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(0, -18 * s, 64 * s, 0, TAU);
  ctx.fill();
  const shards = [[-10, 0, 9, 44], [4, 0, 8, 58], [16, 0, 6, 34]];
  for (const [dx, dy, w, h] of shards) {
    ctx.fillStyle = 'rgba(88,168,190,0.92)';
    ctx.beginPath();
    ctx.moveTo(dx - w * s, dy);
    ctx.lineTo(dx - w * 0.55 * s, -h * s * 0.9);
    ctx.lineTo(dx, -h * s);
    ctx.lineTo(dx + w * 0.6 * s, -h * s * 0.62);
    ctx.lineTo(dx + w * s, dy);
    ctx.closePath();
    ctx.fill();
    ctx.fillStyle = 'rgba(178,238,248,0.55)';
    ctx.beginPath();
    ctx.moveTo(dx - w * 0.3 * s, dy - 2);
    ctx.lineTo(dx - w * 0.1 * s, -h * s * 0.86);
    ctx.lineTo(dx + w * 0.1 * s, dy - 2);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

function drawDeadTree(ctx, o) {
  const s = o.s;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 0, 0, 24 * s, 8 * s, 0.18, 3);
  ctx.strokeStyle = '#574536';
  ctx.lineCap = 'round';
  ctx.lineWidth = 9 * s;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-2 * s, -54 * s);
  ctx.stroke();
  ctx.lineWidth = 5 * s;
  ctx.beginPath();
  ctx.moveTo(-2 * s, -40 * s);
  ctx.lineTo(-22 * s, -68 * s);
  ctx.moveTo(-1 * s, -50 * s);
  ctx.lineTo(19 * s, -74 * s);
  ctx.moveTo(-22 * s, -68 * s);
  ctx.lineTo(-30 * s, -60 * s);
  ctx.moveTo(19 * s, -74 * s);
  ctx.lineTo(27 * s, -88 * s);
  ctx.stroke();
  ctx.strokeStyle = '#6d5844';
  ctx.lineWidth = 2 * s;
  ctx.beginPath();
  ctx.moveTo(-3 * s, -4);
  ctx.lineTo(-4 * s, -50 * s);
  ctx.stroke();
  ctx.restore();
}

// -------------------------------------------------------------------- village
function drawHouse(ctx, o) {
  const { x, y, w, h } = o;
  ctx.save();
  ctx.fillStyle = 'rgba(22,30,20,0.25)';
  roundedRect(ctx, x + 16, y + 24, w, h * 0.9, 12);
  ctx.fill();

  // Walls.
  roundedRect(ctx, x, y + h * 0.34, w, h * 0.66, 5);
  ctx.fillStyle = o.wall;
  ctx.fill();
  ctx.fillStyle = 'rgba(122,92,58,0.18)';
  ctx.fillRect(x, y + h * 0.34, w, 8);

  // Timber framing.
  ctx.strokeStyle = o.timber;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(x + 8, y + h * 0.36);
  ctx.lineTo(x + 8, y + h);
  ctx.moveTo(x + w - 8, y + h * 0.36);
  ctx.lineTo(x + w - 8, y + h);
  ctx.moveTo(x + w * 0.3, y + h * 0.36);
  ctx.lineTo(x + w * 0.3, y + h);
  ctx.moveTo(x + w * 0.7, y + h * 0.36);
  ctx.lineTo(x + w * 0.7, y + h);
  ctx.moveTo(x + 8, y + h * 0.82);
  ctx.lineTo(x + w - 8, y + h * 0.82);
  ctx.stroke();

  // Windows.
  for (const wx of [x + w * 0.15, x + w * 0.72]) {
    const wy = y + h * 0.58;
    const ww = w * 0.13, wh = h * 0.16;
    ctx.fillStyle = '#42321f';
    ctx.fillRect(wx - 3, wy - 3, ww + 6, wh + 6);
    const gl = ctx.createLinearGradient(wx, wy, wx, wy + wh);
    gl.addColorStop(0, '#ffd98d');
    gl.addColorStop(1, '#d98a3f');
    ctx.fillStyle = gl;
    ctx.fillRect(wx, wy, ww, wh);
    ctx.strokeStyle = '#55402a';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(wx + ww / 2, wy);
    ctx.lineTo(wx + ww / 2, wy + wh);
    ctx.moveTo(wx, wy + wh / 2);
    ctx.lineTo(wx + ww, wy + wh / 2);
    ctx.stroke();
  }

  // Door.
  const dw = o.barn ? w * 0.34 : w * 0.17;
  const dh = h * (o.barn ? 0.5 : 0.38);
  const dx = x + w / 2 - dw / 2;
  const dy = y + h - dh;
  ctx.fillStyle = '#3b2b1d';
  ctx.beginPath();
  ctx.moveTo(dx, dy + dh);
  ctx.lineTo(dx, dy + 9);
  ctx.quadraticCurveTo(dx + dw / 2, dy - 8, dx + dw, dy + 9);
  ctx.lineTo(dx + dw, dy + dh);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#6a4e33';
  ctx.lineWidth = 4;
  ctx.stroke();
  if (o.barn) {
    ctx.strokeStyle = '#8a653f';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(dx + dw / 2, dy);
    ctx.lineTo(dx + dw / 2, dy + dh);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(dx + 4, dy + 6);
    ctx.lineTo(dx + dw - 4, dy + dh - 6);
    ctx.moveTo(dx + dw - 4, dy + 6);
    ctx.lineTo(dx + 4, dy + dh - 6);
    ctx.stroke();
  }

  // Roof.
  ctx.beginPath();
  ctx.moveTo(x - 18, y + h * 0.38);
  ctx.lineTo(x + 10, y - 6);
  ctx.lineTo(x + w - 10, y - 6);
  ctx.lineTo(x + w + 18, y + h * 0.38);
  ctx.closePath();
  ctx.fillStyle = o.roof;
  ctx.fill();
  ctx.strokeStyle = o.roofDark;
  ctx.lineWidth = 4;
  ctx.stroke();
  // Shingles.
  ctx.strokeStyle = o.roofDark;
  ctx.globalAlpha = 0.38;
  ctx.lineWidth = 1.6;
  for (let i = 1; i < 7; i++) {
    const t = i / 7;
    ctx.beginPath();
    ctx.moveTo(lerp(x + 6, x + 16, t), lerp(y + 2, y + h * 0.36, t));
    ctx.lineTo(lerp(x + w - 6, x + w - 16, t), lerp(y + 2, y + h * 0.36, t));
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  // Ridge highlight and eave shadow.
  ctx.strokeStyle = 'rgba(255,224,170,0.36)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(x + 12, y - 3);
  ctx.lineTo(x + w - 12, y - 3);
  ctx.stroke();
  ctx.fillStyle = 'rgba(40,38,28,0.24)';
  ctx.fillRect(x + 2, y + h * 0.33, w - 4, 8);
  // Moss on some roofs.
  if (hash2(o.x | 0, o.y | 0, 4) > 0.45) {
    ctx.fillStyle = 'rgba(94,118,60,0.36)';
    for (let i = 0; i < 4; i++) {
      const mx = x + 24 + hash2(i, o.x | 0, 9) * (w - 48);
      const my = y + 20 + hash2(i, o.y | 0, 11) * (h * 0.2);
      ctx.beginPath();
      ctx.ellipse(mx, my, 10 + hash2(i, 2, 3) * 12, 4 + hash2(i, 4, 5) * 4, 0.1, 0, TAU);
      ctx.fill();
    }
  }

  // Chimney.
  if (o.chimney) {
    const cx = x + w * 0.72;
    const cy = y - 18;
    ctx.fillStyle = 'rgba(30,26,20,0.3)';
    ctx.fillRect(cx + 5, cy + 7, 26, 26);
    ctx.fillStyle = '#8b7560';
    ctx.fillRect(cx, cy, 26, 26);
    ctx.fillStyle = '#6d5a48';
    ctx.fillRect(cx, cy, 26, 6);
    ctx.fillStyle = '#a08b73';
    ctx.fillRect(cx + 3, cy + 8, 8, 4);
  }

  // Hanging sign for the Elder's Hall.
  if (o.name) {
    ctx.strokeStyle = '#4f3b27';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(x + w - 30, y + h * 0.5);
    ctx.lineTo(x + w - 4, y + h * 0.5);
    ctx.stroke();
    ctx.fillStyle = '#6b5336';
    roundedRect(ctx, x + w - 22, y + h * 0.47, 20, 26, 3);
    ctx.fill();
    ctx.strokeStyle = '#d8b06b';
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(x + w - 15, y + h * 0.49);
    ctx.lineTo(x + w - 15, y + h * 0.53);
    ctx.moveTo(x + w - 18, y + h * 0.51);
    ctx.lineTo(x + w - 12, y + h * 0.51);
    ctx.stroke();
  }
  ctx.restore();
}

function drawWell(ctx, o, time) {
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 52, 15, 0.25, 4);
  // Roof and posts sit above the stone ring.
  ctx.fillStyle = '#57412c';
  ctx.fillRect(x - 42, y - 74, 7, 62);
  ctx.fillRect(x + 35, y - 74, 7, 62);
  ctx.fillStyle = '#6b4d33';
  ctx.beginPath();
  ctx.moveTo(x - 60, y - 68);
  ctx.lineTo(x - 24, y - 104);
  ctx.lineTo(x + 24, y - 104);
  ctx.lineTo(x + 60, y - 68);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#4b3625';
  ctx.lineWidth = 3;
  ctx.stroke();
  ctx.strokeStyle = 'rgba(238,210,160,0.25)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x - 52, y - 72);
  ctx.lineTo(x - 20, y - 100);
  ctx.stroke();

  // Rope and bucket.
  ctx.strokeStyle = '#7a6647';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x + 2, y - 66);
  ctx.lineTo(x + 2, y - 28);
  ctx.stroke();
  ctx.fillStyle = '#6e5436';
  ctx.fillRect(x - 7, y - 28, 18, 14);
  ctx.strokeStyle = '#3f2f20';
  ctx.lineWidth = 1.5;
  ctx.strokeRect(x - 7, y - 28, 18, 14);

  // Stone ring.
  ctx.fillStyle = '#8f8b7d';
  ctx.beginPath();
  ctx.ellipse(x, y, 48, 34, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#6c685e';
  ctx.beginPath();
  ctx.ellipse(x, y - 2, 39, 26, 0, 0, TAU);
  ctx.fill();
  const water = ctx.createRadialGradient(x - 8, y - 8, 2, x, y, 30);
  water.addColorStop(0, '#5e969c');
  water.addColorStop(1, '#27484f');
  ctx.fillStyle = water;
  ctx.beginPath();
  ctx.ellipse(x, y - 2, 31, 20, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = `rgba(190,230,225,${0.2 + Math.sin(time * 1.6) * 0.08})`;
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.ellipse(x - 6, y - 5, 12, 5, 0, 0, TAU);
  ctx.stroke();
  // Stones on the rim.
  ctx.fillStyle = '#a29d8d';
  for (let i = 0; i < 9; i++) {
    const a = (i / 9) * TAU + 0.25;
    ctx.beginPath();
    ctx.ellipse(x + Math.cos(a) * 44, y + Math.sin(a) * 30, 7, 4.6, a, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawShrine(ctx, o, time) {
  const x = o.x, y = o.y;
  const pulse = 0.6 + Math.sin(time * 1.4) * 0.2;
  ctx.save();
  shadow(ctx, x, y, 34, 12, 0.22, 3);
  ctx.fillStyle = '#5a6350';
  ctx.beginPath();
  ctx.ellipse(x, y + 4, 34, 18, 0, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#7d8470';
  ctx.beginPath();
  ctx.ellipse(x, y, 28, 14, 0, 0, TAU);
  ctx.fill();
  // Standing stone.
  ctx.fillStyle = '#71766a';
  ctx.beginPath();
  ctx.moveTo(x - 19, y + 4);
  ctx.lineTo(x - 23, y - 48);
  ctx.lineTo(x - 9, y - 76);
  ctx.lineTo(x + 11, y - 72);
  ctx.lineTo(x + 21, y - 42);
  ctx.lineTo(x + 18, y + 4);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = '#8d917f';
  ctx.beginPath();
  ctx.moveTo(x - 14, y + 2);
  ctx.lineTo(x - 16, y - 46);
  ctx.lineTo(x - 5, y - 68);
  ctx.lineTo(x + 1, y - 40);
  ctx.lineTo(x + 1, y + 2);
  ctx.closePath();
  ctx.fill();
  // Glowing rune.
  ctx.strokeStyle = `rgba(150,236,158,${pulse})`;
  ctx.lineWidth = 3;
  ctx.shadowColor = 'rgba(120,230,140,0.8)';
  ctx.shadowBlur = 10;
  ctx.beginPath();
  ctx.moveTo(x - 4, y - 48);
  ctx.lineTo(x + 5, y - 38);
  ctx.lineTo(x - 5, y - 28);
  ctx.lineTo(x + 5, y - 18);
  ctx.stroke();
  ctx.shadowBlur = 0;
  // Moss and offerings.
  ctx.fillStyle = 'rgba(95,125,66,0.5)';
  ctx.beginPath();
  ctx.ellipse(x - 12, y - 2, 10, 5, 0.3, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#a79b7d';
  for (let i = 0; i < 4; i++) {
    ctx.beginPath();
    ctx.arc(x - 24 + i * 10, y + 16 + Math.sin(i * 2) * 4, 3, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawCampfire(ctx, o, time) {
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 36, 12, 0.25, 3);
  ctx.fillStyle = '#69665c';
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * TAU;
    ctx.beginPath();
    ctx.ellipse(x + Math.cos(a) * 25, y + Math.sin(a) * 14, 7, 4.6, a, 0, TAU);
    ctx.fill();
  }
  ctx.strokeStyle = '#4f3623';
  ctx.lineWidth = 7;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x - 15, y + 5);
  ctx.lineTo(x + 15, y - 5);
  ctx.moveTo(x - 13, y - 6);
  ctx.lineTo(x + 14, y + 6);
  ctx.stroke();
  const flick = 1 + Math.sin(time * 8.3) * 0.08 + Math.sin(time * 13.7) * 0.05;
  const glow = ctx.createRadialGradient(x, y - 12, 2, x, y - 12, 44);
  glow.addColorStop(0, 'rgba(255,196,96,0.5)');
  glow.addColorStop(1, 'rgba(255,140,50,0)');
  ctx.fillStyle = glow;
  ctx.beginPath();
  ctx.arc(x, y - 12, 44, 0, TAU);
  ctx.fill();
  // Flames.
  const flames = [
    [0, 21 * flick, 26 * flick, '#c94e22'],
    [-5, 14 * flick, 20 * flick, '#ef7c2c'],
    [4, 10 * flick, 15 * flick, '#ffb347'],
    [0, 5 * flick, 9 * flick, '#ffe9a3']
  ];
  for (const [dx, w, h, color] of flames) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x + dx - w * 0.5, y - 2);
    ctx.quadraticCurveTo(x + dx - w * 0.6 + Math.sin(time * 5 + dx) * 3, y - h * 0.6, x + dx + Math.sin(time * 7 + dx) * 4, y - h);
    ctx.quadraticCurveTo(x + dx + w * 0.7, y - h * 0.5, x + dx + w * 0.5, y - 2);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
}

function drawStall(ctx, o) {
  const { x, y, w, h } = o;
  ctx.save();
  ctx.fillStyle = 'rgba(22,30,20,0.22)';
  roundedRect(ctx, x + 8, y + 14, w, h, 5);
  ctx.fill();
  // Table.
  roundedRect(ctx, x + 6, y + h * 0.52, w - 12, h * 0.42, 3);
  ctx.fillStyle = '#8b683f';
  ctx.fill();
  ctx.fillStyle = '#a47d4e';
  ctx.fillRect(x + 10, y + h * 0.55, w - 20, 4);
  // Posts.
  ctx.fillStyle = '#5a4129';
  ctx.fillRect(x + 4, y + 8, 6, h * 0.6);
  ctx.fillRect(x + w - 10, y + 8, 6, h * 0.6);
  // Awning stripes.
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(x - 6, y + 6);
  ctx.lineTo(x + w + 6, y + 6);
  ctx.lineTo(x + w + 12, y + h * 0.5);
  ctx.lineTo(x - 12, y + h * 0.5);
  ctx.closePath();
  ctx.clip();
  for (let i = 0; i < 7; i++) {
    ctx.fillStyle = i % 2 ? '#e3d3ac' : o.hue;
    ctx.fillRect(x - 12 + i * (w + 24) / 7, y + 2, (w + 24) / 7, h * 0.55);
  }
  ctx.fillStyle = 'rgba(38,32,22,0.2)';
  ctx.fillRect(x - 12, y + 2, w + 24, h * 0.1);
  ctx.restore();
  // Produce.
  const colors = ['#c25a38', '#d8a23d', '#6e8b3f', '#b4423e'];
  for (let i = 0; i < 9; i++) {
    ctx.fillStyle = colors[i % colors.length];
    ctx.beginPath();
    ctx.arc(x + 18 + (i % 4) * 22, y + h * 0.6 + Math.floor(i / 4) * 10, 4.4, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

function drawFence(ctx, o) {
  const { x1, y1, x2, y2 } = o;
  const len = Math.hypot(x2 - x1, y2 - y1);
  const dx = (x2 - x1) / len;
  const dy = (y2 - y1) / len;
  ctx.save();
  ctx.strokeStyle = 'rgba(26,32,22,0.18)';
  ctx.lineWidth = 10;
  ctx.beginPath();
  ctx.moveTo(x1 + 5, y1 + 6);
  ctx.lineTo(x2 + 5, y2 + 6);
  ctx.stroke();
  // Two rails, drawn as a shallow height impression.
  ctx.strokeStyle = '#6e5133';
  ctx.lineWidth = 5;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1, y1 - 14);
  ctx.lineTo(x2, y2 - 14);
  ctx.moveTo(x1, y1 - 6);
  ctx.lineTo(x2, y2 - 6);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(197,163,111,0.4)';
  ctx.lineWidth = 1.6;
  ctx.beginPath();
  ctx.moveTo(x1, y1 - 16);
  ctx.lineTo(x2, y2 - 16);
  ctx.stroke();
  const posts = Math.max(2, Math.round(len / 62));
  for (let i = 0; i <= posts; i++) {
    const t = i / posts;
    const x = x1 + (x2 - x1) * t;
    const y = y1 + (y2 - y1) * t;
    ctx.fillStyle = '#56402a';
    ctx.fillRect(x - 4, y - 24, 8, 26);
    ctx.fillStyle = 'rgba(211,177,123,0.35)';
    ctx.fillRect(x - 3, y - 23, 2, 22);
  }
  void dx; void dy;
  ctx.restore();
}

function drawLantern(ctx, o, time) {
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 14, 5, 0.2, 2);
  ctx.fillStyle = '#503b27';
  ctx.fillRect(x - 3, y - 58, 6, 60);
  ctx.fillRect(x - 14, y - 58, 28, 4);
  ctx.strokeStyle = '#3e2d1e';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(x + 10, y - 55);
  ctx.lineTo(x + 10, y - 46);
  ctx.stroke();
  ctx.fillStyle = '#3d2e20';
  ctx.fillRect(x + 3, y - 47, 14, 18);
  const glow = ctx.createLinearGradient(x + 5, y - 45, x + 5, y - 31);
  glow.addColorStop(0, '#ffe2a1');
  glow.addColorStop(1, '#e29a45');
  ctx.fillStyle = glow;
  ctx.fillRect(x + 5, y - 45, 10, 14);
  ctx.fillStyle = 'rgba(255,214,138,0.25)';
  ctx.beginPath();
  ctx.arc(x + 10, y - 38, 13 + Math.sin(time * 4.1) * 1.6, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#4d3826';
  ctx.fillRect(x + 2, y - 49, 16, 3);
  ctx.restore();
}

function drawCrate(ctx, o) {
  const s = o.s || 1;
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 20 * s, 7 * s, 0.2, 2);
  const w = 32 * s, h = 28 * s;
  ctx.fillStyle = '#8a653e';
  ctx.fillRect(x - w / 2, y - h, w, h);
  ctx.fillStyle = '#a17a4d';
  ctx.fillRect(x - w / 2 + 3, y - h + 3, w - 6, 5);
  ctx.strokeStyle = '#5f4429';
  ctx.lineWidth = 3;
  ctx.strokeRect(x - w / 2, y - h, w, h);
  ctx.beginPath();
  ctx.moveTo(x - w / 2 + 3, y - h + 3);
  ctx.lineTo(x + w / 2 - 3, y - 3);
  ctx.moveTo(x + w / 2 - 3, y - h + 3);
  ctx.lineTo(x - w / 2 + 3, y - 3);
  ctx.stroke();
  ctx.restore();
}

function drawBarrel(ctx, o) {
  const s = o.s || 1;
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 16 * s, 6 * s, 0.2, 2);
  ctx.fillStyle = '#75532f';
  ctx.beginPath();
  ctx.ellipse(x, y - 20 * s, 15 * s, 9 * s, 0, 0, TAU);
  ctx.fill();
  ctx.fillRect(x - 15 * s, y - 20 * s, 30 * s, 20 * s);
  ctx.fillStyle = '#8c6438';
  ctx.beginPath();
  ctx.ellipse(x, y - 20 * s, 15 * s, 9 * s, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#4a3421';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x - 15 * s, y - 14 * s);
  ctx.lineTo(x + 15 * s, y - 14 * s);
  ctx.moveTo(x - 15 * s, y - 4 * s);
  ctx.lineTo(x + 15 * s, y - 4 * s);
  ctx.stroke();
  ctx.fillStyle = '#3f2c1c';
  ctx.beginPath();
  ctx.ellipse(x, y - 20 * s, 8 * s, 5 * s, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawHay(ctx, o) {
  const s = o.s || 1;
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 28 * s, 9 * s, 0.2, 2);
  ctx.fillStyle = '#b99a55';
  ctx.beginPath();
  ctx.ellipse(x, y - 12 * s, 28 * s, 18 * s, 0, Math.PI, TAU);
  ctx.fill();
  ctx.fillRect(x - 28 * s, y - 12 * s, 56 * s, 12 * s);
  ctx.strokeStyle = 'rgba(135,106,48,0.6)';
  ctx.lineWidth = 2;
  for (let i = -2; i <= 2; i++) {
    ctx.beginPath();
    ctx.moveTo(x + i * 10 * s, y - 28 * s);
    ctx.lineTo(x + i * 11 * s, y - 2 * s);
    ctx.stroke();
  }
  ctx.fillStyle = 'rgba(240,214,145,0.35)';
  ctx.beginPath();
  ctx.ellipse(x - 8 * s, y - 22 * s, 14 * s, 6 * s, -0.2, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawBench(ctx, o) {
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 30, 7, 0.2, 2);
  ctx.fillStyle = '#6c5133';
  ctx.fillRect(x - 30, y - 18, 60, 10);
  ctx.fillStyle = '#886943';
  ctx.fillRect(x - 30, y - 21, 60, 5);
  ctx.fillStyle = '#4f3a24';
  ctx.fillRect(x - 26, y - 12, 5, 12);
  ctx.fillRect(x + 21, y - 12, 5, 12);
  ctx.restore();
}

function drawCart(ctx, o) {
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 40, 12, 0.22, 3);
  ctx.fillStyle = '#7d5c37';
  ctx.fillRect(x - 28, y - 30, 56, 26);
  ctx.strokeStyle = '#4f3922';
  ctx.lineWidth = 3;
  ctx.strokeRect(x - 28, y - 30, 56, 26);
  ctx.fillStyle = '#5d4329';
  ctx.beginPath();
  ctx.arc(x - 24, y - 2, 12, 0, TAU);
  ctx.arc(x + 24, y - 2, 12, 0, TAU);
  ctx.fill();
  ctx.fillStyle = '#a98251';
  ctx.beginPath();
  ctx.arc(x - 24, y - 2, 5, 0, TAU);
  ctx.arc(x + 24, y - 2, 5, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#6b4c2e';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(x - 28, y - 18);
  ctx.lineTo(x - 58, y - 8);
  ctx.stroke();
  // Hay poking out.
  ctx.strokeStyle = '#c4a45e';
  ctx.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.moveTo(x - 20 + i * 9, y - 28);
    ctx.lineTo(x - 14 + i * 9, y - 40);
    ctx.stroke();
  }
  ctx.restore();
}

function drawSign(ctx, o) {
  const x = o.x, y = o.y;
  ctx.save();
  shadow(ctx, x, y, 18, 5, 0.2, 2);
  ctx.fillStyle = '#584027';
  ctx.fillRect(x - 3, y - 58, 6, 60);
  ctx.fillStyle = '#7c5c37';
  ctx.beginPath();
  ctx.moveTo(x - 30, y - 64);
  ctx.lineTo(x + 22, y - 64);
  ctx.lineTo(x + 34, y - 53);
  ctx.lineTo(x + 22, y - 42);
  ctx.lineTo(x - 30, y - 42);
  ctx.closePath();
  ctx.fill();
  ctx.strokeStyle = '#4b3520';
  ctx.lineWidth = 2.5;
  ctx.stroke();
  ctx.strokeStyle = '#3c2b1a';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(x - 20, y - 56);
  ctx.lineTo(x + 12, y - 56);
  ctx.moveTo(x - 20, y - 50);
  ctx.lineTo(x + 4, y - 50);
  ctx.stroke();
  // Second, smaller board.
  ctx.fillStyle = '#6e5231';
  ctx.fillRect(x + 2, y - 36, 28, 12);
  ctx.strokeRect(x + 2, y - 36, 28, 12);
  ctx.restore();
}

// ------------------------------------------------------------------ water bits
function drawReed(ctx, o, time) {
  const s = o.s;
  const sway = Math.sin(time * 1.4 + o.seed) * 4;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.strokeStyle = 'rgba(94,120,60,0.8)';
  ctx.lineWidth = 2;
  ctx.lineCap = 'round';
  for (let i = 0; i < 5; i++) {
    const dx = (i - 2) * 4;
    const h = (22 + hash2(i, o.seed | 0, 5) * 22) * s;
    ctx.beginPath();
    ctx.moveTo(dx, 0);
    ctx.quadraticCurveTo(dx + sway * 0.4, -h * 0.6, dx + sway, -h);
    ctx.stroke();
  }
  ctx.fillStyle = '#7c6335';
  ctx.beginPath();
  ctx.ellipse(sway * 0.6 - 2, -40 * s, 2.4, 6, 0.15, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawLily(ctx, o, time) {
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.rotate(Math.sin(time * 0.3 + o.seed) * 0.05);
  ctx.fillStyle = 'rgba(72,112,62,0.85)';
  ctx.beginPath();
  ctx.ellipse(0, 0, 16 * o.s, 10 * o.s, 0.2, 0, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(38,70,45,0.4)';
  ctx.beginPath();
  ctx.ellipse(2, 2, 10 * o.s, 6 * o.s, 0.2, 0, TAU);
  ctx.fill();
  if (o.s > 1) {
    ctx.fillStyle = '#efe6c8';
    ctx.beginPath();
    ctx.arc(3, -2, 3.2 * o.s, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

// --------------------------------------------------------------- forest details
function drawLog(ctx, o) {
  const s = o.s;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.rotate(o.angle);
  shadow(ctx, 0, 2, 42 * s, 9 * s, 0.18, 2);
  ctx.fillStyle = '#5c452c';
  roundedRect(ctx, -44 * s, -10 * s, 88 * s, 20 * s, 9 * s);
  ctx.fill();
  ctx.fillStyle = '#755a3a';
  roundedRect(ctx, -42 * s, -8 * s, 84 * s, 12 * s, 6 * s);
  ctx.fill();
  ctx.strokeStyle = 'rgba(46,34,22,0.5)';
  ctx.lineWidth = 1.6;
  for (let i = -3; i <= 3; i++) {
    ctx.beginPath();
    ctx.moveTo(i * 12 * s, -7 * s);
    ctx.lineTo(i * 12 * s + 8 * s, 3 * s);
    ctx.stroke();
  }
  ctx.fillStyle = '#8a6d45';
  ctx.beginPath();
  ctx.ellipse(-44 * s, 0, 5 * s, 10 * s, 0, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawStump(ctx, o) {
  const s = o.s;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 0, 0, 16 * s, 5 * s, 0.18, 2);
  ctx.fillStyle = '#5d4830';
  ctx.beginPath();
  ctx.ellipse(0, -5 * s, 14 * s, 8 * s, 0, 0, TAU);
  ctx.fill();
  ctx.fillRect(-14 * s, -10 * s, 28 * s, 10 * s);
  ctx.fillStyle = '#8d6d46';
  ctx.beginPath();
  ctx.ellipse(0, -10 * s, 14 * s, 8 * s, 0, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#6c5235';
  ctx.lineWidth = 1.2;
  for (let i = 1; i < 4; i++) {
    ctx.beginPath();
    ctx.ellipse(0, -10 * s, i * 3.2 * s, i * 1.8 * s, 0, 0, TAU);
    ctx.stroke();
  }
  ctx.restore();
}

function drawFern(ctx, o, time) {
  const s = o.s;
  const sway = Math.sin(time * 0.9 + o.seed) * 0.08;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.rotate(sway);
  ctx.strokeStyle = 'rgba(66,104,56,0.85)';
  ctx.lineWidth = 2 * s;
  ctx.lineCap = 'round';
  for (let i = 0; i < 6; i++) {
    const a = -Math.PI * 0.86 + (i / 5) * Math.PI * 0.72;
    const len = (16 + hash2(i, o.seed | 0, 3) * 14) * s;
    const ex = Math.cos(a) * len;
    const ey = Math.sin(a) * len;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.quadraticCurveTo(ex * 0.5, ey * 0.5 - 6 * s, ex, ey);
    ctx.stroke();
    // Fronds.
    ctx.lineWidth = 1.2 * s;
    for (let j = 1; j < 4; j++) {
      const t = j / 4;
      const px = ex * t;
      const py = ey * t - 4 * s * t;
      const side = j % 2 ? 1 : -1;
      ctx.beginPath();
      ctx.moveTo(px, py);
      ctx.lineTo(px + Math.cos(a + side * 1.2) * 5 * s, py + Math.sin(a + side * 1.2) * 5 * s);
      ctx.stroke();
    }
    ctx.lineWidth = 2 * s;
  }
  ctx.restore();
}

function drawMushroom(ctx, o) {
  const s = o.s;
  ctx.save();
  ctx.translate(o.x, o.y);
  shadow(ctx, 0, 0, 8 * s, 3 * s, 0.15, 1);
  ctx.strokeStyle = '#d8cfb2';
  ctx.lineWidth = 3 * s;
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(0, -9 * s);
  ctx.stroke();
  const cap = hash2(o.x | 0, o.y | 0, 5) > 0.5 ? '#b4513d' : '#c39a54';
  ctx.fillStyle = cap;
  ctx.beginPath();
  ctx.ellipse(0, -11 * s, 8 * s, 5 * s, 0, Math.PI, TAU);
  ctx.fill();
  ctx.fillStyle = 'rgba(247,240,219,0.7)';
  ctx.beginPath();
  ctx.arc(-2 * s, -12 * s, 1.6 * s, 0, TAU);
  ctx.arc(3 * s, -13 * s, 1.2 * s, 0, TAU);
  ctx.fill();
  ctx.restore();
}

function drawFlowers(ctx, o, time) {
  const s = o.s;
  const sway = Math.sin(time * 1.1 + o.seed) * 1.4;
  ctx.save();
  ctx.translate(o.x, o.y);
  ctx.strokeStyle = 'rgba(88,120,58,0.8)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 5; i++) {
    const dx = (i - 2) * 5 * s;
    const h = (10 + hash2(i, o.seed | 0, 4) * 12) * s;
    ctx.beginPath();
    ctx.moveTo(dx, 0);
    ctx.quadraticCurveTo(dx + sway * 0.4, -h * 0.6, dx + sway, -h);
    ctx.stroke();
    const c = o.bright
      ? (i % 2 ? '#f2e6b2' : '#d9c4e8')
      : (i % 2 ? '#ead9a4' : '#c9b3d8');
    ctx.fillStyle = c;
    ctx.beginPath();
    ctx.arc(dx + sway, -h, 2.2 * s, 0, TAU);
    ctx.fill();
    ctx.fillStyle = 'rgba(226,170,54,0.8)';
    ctx.beginPath();
    ctx.arc(dx + sway, -h, 0.9 * s, 0, TAU);
    ctx.fill();
  }
  ctx.restore();
}

// Keyboard, mouse and touch input. Touch uses a dynamic left-thumb stick,
// a right-half aim drag, and two action buttons.
export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressed = new Set();
    this.mouse = { x: window.innerWidth / 2, y: window.innerHeight / 2, down: false, seen: false };
    this.touchThrowHeld = false;
    this.burstQueued = false;
    this.throwQueue = 0;
    this.aimTouch = null;
    this.lastAimDir = { x: 1, y: 0 };
    this.facing = { x: 1, y: 0 };

    this.joy = { active: false, pointer: null, ox: 0, oy: 0, dx: 0, dy: 0, mag: 0 };
    this.coarse = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    this.touchMode = this.coarse || window.innerWidth < 820;
    if (this.touchMode) document.body.classList.add('touch-ui');
    if (this.coarse) document.body.classList.add('coarse');

    this.bind();
  }

  bind() {
    window.addEventListener('keydown', (e) => {
      if (['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Tab'].includes(e.code)) e.preventDefault();
      if (!this.keys.has(e.code)) this.pressed.add(e.code);
      this.keys.add(e.code);
    });
    window.addEventListener('keyup', (e) => {
      this.keys.delete(e.code);
    });
    window.addEventListener('blur', () => {
      this.keys.clear();
      this.mouse.down = false;
      this.touchThrowHeld = false;
      this.resetJoystick();
    });

    window.addEventListener('mousemove', (e) => {
      this.mouse.x = e.clientX;
      this.mouse.y = e.clientY;
      this.mouse.seen = true;
    });
    window.addEventListener('mousedown', (e) => {
      if (e.target === this.canvas && e.button === 0) this.mouse.down = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.mouse.down = false;
    });
    window.addEventListener('contextmenu', (e) => e.preventDefault());

    const c = this.canvas;
    c.addEventListener('pointerdown', (e) => {
      if (e.pointerType === 'mouse') {
        if (e.button === 0) this.mouse.down = true;
        this.mouse.x = e.clientX;
        this.mouse.y = e.clientY;
        this.mouse.seen = true;
        return;
      }
      // Touch aim on the right half of the world.
      if (e.clientX < window.innerWidth * 0.4) return;
      e.preventDefault();
      this.aimTouch = { id: e.pointerId, sx: e.clientX, sy: e.clientY, x: e.clientX, y: e.clientY, moved: false };
      try { c.setPointerCapture(e.pointerId); } catch {}
    });
    c.addEventListener('pointermove', (e) => {
      if (e.pointerType === 'mouse') {
        this.mouse.x = e.clientX;
        this.mouse.y = e.clientY;
        return;
      }
      if (!this.aimTouch || this.aimTouch.id !== e.pointerId) return;
      e.preventDefault();
      const a = this.aimTouch;
      a.x = e.clientX;
      a.y = e.clientY;
      const dx = a.x - a.sx;
      const dy = a.y - a.sy;
      if (Math.hypot(dx, dy) > 12) a.moved = true;
      if (a.moved) {
        const l = Math.hypot(dx, dy) || 1;
        this.lastAimDir = { x: dx / l, y: dy / l };
      }
    });
    const endAim = (e) => {
      if (this.aimTouch && this.aimTouch.id === e.pointerId) {
        const a = this.aimTouch;
        if (a.moved) {
          const dx = a.x - a.sx;
          const dy = a.y - a.sy;
          const l = Math.hypot(dx, dy) || 1;
          this.lastAimDir = { x: dx / l, y: dy / l };
        }
        this.throwQueue = Math.min(2, this.throwQueue + 1);
        this.aimTouch = null;
      }
    };
    c.addEventListener('pointerup', endAim);
    c.addEventListener('pointercancel', (e) => {
      if (this.aimTouch && this.aimTouch.id === e.pointerId) this.aimTouch = null;
    });

    this.bindJoystick();
    this.bindButtons();
  }

  bindJoystick() {
    const zone = document.getElementById('joy-zone');
    const base = document.getElementById('joy-base');
    const knob = document.getElementById('joy-knob');
    if (!zone || !base || !knob) return;
    const radius = 46;
    const start = (e) => {
      if (e.pointerType === 'mouse') return;
      e.preventDefault();
      this.joy.active = true;
      this.joy.pointer = e.pointerId;
      this.joy.ox = e.clientX;
      this.joy.oy = e.clientY;
      base.style.left = e.clientX + 'px';
      base.style.top = e.clientY + 'px';
      base.style.display = 'block';
      document.body.classList.add('joystick-active');
      knob.style.transform = 'translate(0px, 0px)';
      try { zone.setPointerCapture(e.pointerId); } catch {}
    };
    const move = (e) => {
      if (!this.joy.active || this.joy.pointer !== e.pointerId) return;
      e.preventDefault();
      let dx = e.clientX - this.joy.ox;
      let dy = e.clientY - this.joy.oy;
      const d = Math.hypot(dx, dy);
      if (d > radius) {
        dx = (dx / d) * radius;
        dy = (dy / d) * radius;
      }
      this.joy.dx = dx / radius;
      this.joy.dy = dy / radius;
      this.joy.mag = Math.min(1, d / radius);
      knob.style.transform = `translate(${dx}px, ${dy}px)`;
    };
    const end = (e) => {
      if (this.joy.pointer !== e.pointerId) return;
      this.resetJoystick();
    };
    zone.addEventListener('pointerdown', start);
    zone.addEventListener('pointermove', move);
    zone.addEventListener('pointerup', end);
    zone.addEventListener('pointercancel', end);
  }

  resetJoystick() {
    this.joy.active = false;
    this.joy.pointer = null;
    this.joy.dx = 0;
    this.joy.dy = 0;
    this.joy.mag = 0;
    const base = document.getElementById('joy-base');
    if (base) base.style.display = 'none';
    document.body.classList.remove('joystick-active');
  }

  bindButtons() {
    const throwBtn = document.getElementById('btn-throw');
    const burstBtn = document.getElementById('btn-burst');
    if (throwBtn) {
      const on = (e) => {
        e.preventDefault();
        this.touchThrowHeld = true;
        this.autoAim = true;
      };
      const off = (e) => {
        e.preventDefault();
        this.touchThrowHeld = false;
      };
      throwBtn.addEventListener('pointerdown', on);
      throwBtn.addEventListener('pointerup', off);
      throwBtn.addEventListener('pointercancel', off);
      throwBtn.addEventListener('pointerleave', off);
    }
    if (burstBtn) {
      burstBtn.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        this.burstQueued = true;
      });
    }
  }

  justPressed(code) {
    return this.pressed.has(code);
  }

  consumePressed(code) {
    if (!this.pressed.has(code)) return false;
    this.pressed.delete(code);
    return true;
  }

  getMove() {
    let x = 0;
    let y = 0;
    if (this.keys.has('KeyA') || this.keys.has('ArrowLeft')) x -= 1;
    if (this.keys.has('KeyD') || this.keys.has('ArrowRight')) x += 1;
    if (this.keys.has('KeyW') || this.keys.has('ArrowUp')) y -= 1;
    if (this.keys.has('KeyS') || this.keys.has('ArrowDown')) y += 1;
    if (this.joy.active) {
      x += this.joy.dx;
      y += this.joy.dy;
    }
    const len = Math.hypot(x, y);
    if (len > 1) { x /= len; y /= len; }
    if (len > 0.01) this.facing = { x: x / (len || 1), y: y / (len || 1) };
    return { x, y, mag: Math.min(1, len) };
  }

  isThrowing() {
    return this.mouse.down || this.touchThrowHeld;
  }

  consumeThrowQueue() {
    if (this.throwQueue <= 0) return false;
    this.throwQueue--;
    return true;
  }

  consumeBurst() {
    if (!this.burstQueued) return false;
    this.burstQueued = false;
    return true;
  }

  aimMode() {
    if (this.aimTouch) return 'touch';
    if (this.touchThrowHeld) return 'auto';
    return 'mouse';
  }

  endFrame() {
    this.pressed.clear();
  }
}

import { TAU, clamp, dist, hash2, range } from './util.js';

export function initFx(game) {
  game.particles = [];
  game.effects = [];
  game.texts = [];
  game.pickups = [];
}

export function addParticle(game, p) {
  if (game.particles.length > 620) game.particles.shift();
  p.life = p.life ?? 1;
  p.maxLife = p.maxLife ?? p.life;
  p.vx = p.vx ?? 0;
  p.vy = p.vy ?? 0;
  p.size = p.size ?? 4;
  p.color = p.color ?? '180,170,140';
  p.drag = p.drag ?? 1.5;
  p.gravity = p.gravity ?? 0;
  p.rot = p.rot ?? 0;
  p.spin = p.spin ?? 0;
  p.alpha = p.alpha ?? 1;
  game.particles.push(p);
  return p;
}

export function puff(game, x, y, count = 8, color = '181,164,126', power = 1) {
  for (let i = 0; i < count; i++) {
    const a = Math.random() * TAU;
    const sp = range(Math.random, 20, 90) * power;
    addParticle(game, {
      kind: 'dust', x: x + Math.cos(a) * range(Math.random, 2, 14), y: y + Math.sin(a) * range(Math.random, 2, 10),
      vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.55 - 8,
      life: range(Math.random, 0.45, 0.9), size: range(Math.random, 3, 8) * power, color,
      drag: 3.2
    });
  }
}

export function debris(game, x, y, count = 10, color = '138,133,120', power = 1) {
  for (let i = 0; i < count; i++) {
    const a = -Math.PI / 2 + (Math.random() - 0.5) * 3.2;
    const sp = range(Math.random, 60, 220) * power;
    addParticle(game, {
      kind: 'debris', x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp * 0.6 - 90,
      life: range(Math.random, 0.35, 0.75), size: range(Math.random, 2, 5) * power, color,
      gravity: 520, drag: 0.4, spin: range(Math.random, -12, 12), rot: Math.random() * TAU
    });
  }
}

export function sparks(game, x, y, count = 6, color = '255,206,130') {
  for (let i = 0; i < count; i++) {
    const a = Math.random() * TAU;
    const sp = range(Math.random, 40, 160);
    addParticle(game, {
      kind: 'spark', x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
      life: range(Math.random, 0.2, 0.5), size: range(Math.random, 1.5, 3.2), color, drag: 2.4
    });
  }
}

export function addRing(game, x, y, r0, r1, color = '208,178,120', life = 0.5, width = 4) {
  game.effects.push({ kind: 'ring', x, y, r0, r1, color, life, maxLife: life, width });
}

export function addTelegraph(game, x, y, r, life = 0.7, color = '212,86,68') {
  game.effects.push({ kind: 'telegraph', x, y, r, color, life, maxLife: life });
}

export function addText(game, x, y, text, color = '#f0d79e', size = 14) {
  if (game.texts.length > 40) game.texts.shift();
  game.texts.push({ x, y, text, color, size, life: 1, maxLife: 1, vy: -44, drift: (Math.random() - 0.5) * 18 });
}

export function spawnPickup(game, x, y, kind, value = 1, scatter = true) {
  const a = Math.random() * TAU;
  const sp = scatter ? range(Math.random, 40, 140) : 0;
  game.pickups.push({
    x, y, kind, value,
    vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
    bob: Math.random() * 6, life: 26,
    collected: false
  });
}

export function updatePickups(game, dt) {
  const p = game.player;
  for (const it of game.pickups) {
    it.life -= dt;
    it.bob += dt * 3.4;
    it.x += it.vx * dt;
    it.y += it.vy * dt;
    it.vx *= Math.exp(-3.5 * dt);
    it.vy *= Math.exp(-3.5 * dt);
    const d = dist(it.x, it.y, p.x, p.y);
    if (d < 190) {
      const pull = 520 * (1 - d / 190) + 60;
      it.x += ((p.x - it.x) / (d || 1)) * pull * dt;
      it.y += ((p.y - it.y) / (d || 1)) * pull * dt;
    }
    if (d < 24) {
      it.collected = true;
      if (it.kind === 'heart') {
        if (p.hp < p.maxHp) {
          const heal = Math.min(it.value, p.maxHp - p.hp);
          p.hp += heal;
          addText(game, p.x, p.y - 30, '+' + Math.round(heal) + ' life', '#9fe08a', 14);
          game.audio.play('heal');
        } else {
          p.essence += 3;
          game.stats.essence += 3;
          game.audio.play('pickup');
        }
      } else {
        p.essence += it.value;
        game.stats.essence += it.value;
        game.audio.play('pickup');
        if (game.pickups.length < 4) addText(game, it.x, it.y - 16, '+' + it.value, '#ecc47c', 12);
      }
    }
  }
  game.pickups = game.pickups.filter((it) => !it.collected && it.life > 0);
}

export function updateFx(game, dt) {
  const parts = game.particles;
  for (let i = parts.length - 1; i >= 0; i--) {
    const p = parts[i];
    p.life -= dt;
    if (p.life <= 0) { parts.splice(i, 1); continue; }
    const drag = p.drag ? Math.exp(-p.drag * dt) : 1;
    p.vx *= drag;
    p.vy *= drag;
    if (p.kind === 'smoke' || p.kind === 'fog') {
      p.x += (p.vx + 8) * dt;
      p.y += (p.vy - 6) * dt;
      p.size += dt * (p.kind === 'fog' ? 26 : 13);
    } else if (p.kind === 'ember') {
      p.x += (p.vx + Math.sin(game.time * 5 + p.y * 0.03) * 12) * dt;
      p.y += (p.vy - 22) * dt;
    } else if (p.kind === 'leaf') {
      p.x += (p.vx + Math.sin(game.time * 1.7 + p.rot) * 16) * dt;
      p.y += (p.vy + 8) * dt;
      p.rot += p.spin * dt;
    } else if (p.kind === 'firefly') {
      p.x += Math.sin(game.time * 0.8 + p.seed) * 13 * dt;
      p.y += Math.cos(game.time * 0.64 + p.seed * 1.7) * 10 * dt;
    } else {
      p.vy += (p.gravity || 0) * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
    }
    p.rot += (p.spin || 0) * dt;
  }

  for (let i = game.effects.length - 1; i >= 0; i--) {
    const e = game.effects[i];
    e.life -= dt;
    if (e.life <= 0) game.effects.splice(i, 1);
  }

  for (let i = game.texts.length - 1; i >= 0; i--) {
    const t = game.texts[i];
    t.life -= dt;
    t.y += t.vy * dt;
    t.x += t.drift * dt;
    t.vy *= 0.96;
    if (t.life <= 0) game.texts.splice(i, 1);
  }
}

export function updateAmbient(game, dt) {
  const px = game.player.x;
  const py = game.player.y;
  for (const em of game.world.emitters) {
    const d = dist(em.x, em.y, px, py);
    if (d > 1500) continue;
    em.acc += dt * em.rate;
    while (em.acc >= 1) {
      em.acc -= 1;
      const a = Math.random() * TAU;
      const rr = Math.random() * (em.radius || 40);
      const x = em.x + Math.cos(a) * rr;
      const y = em.y + Math.sin(a) * rr;
      switch (em.type) {
        case 'smoke':
          addParticle(game, {
            kind: 'smoke', x, y, vx: 4 + Math.random() * 6, vy: -14 - Math.random() * 10,
            life: 3.2 + Math.random() * 1.6, size: 7 + Math.random() * 7, color: '168,160,144', alpha: 0.3, drag: 0.1
          });
          break;
        case 'ember':
          addParticle(game, {
            kind: 'ember', x, y, vx: (Math.random() - 0.5) * 18, vy: -30 - Math.random() * 30,
            life: 0.7 + Math.random() * 0.9, size: 1.5 + Math.random() * 2, color: Math.random() > 0.4 ? '255,168,72' : '255,214,128', drag: 0.6
          });
          break;
        case 'fog':
          if (game.particles.filter((p) => p.kind === 'fog').length > 20) break;
          addParticle(game, {
            kind: 'fog', x, y, vx: (Math.random() - 0.5) * 8, vy: -4 - Math.random() * 6,
            life: 5 + Math.random() * 4, size: 34 + Math.random() * 40, color: '160,178,172', alpha: 0.1, drag: 0.05
          });
          break;
        case 'firefly':
          addParticle(game, {
            kind: 'firefly', x, y, life: 3.6 + Math.random() * 3.4, size: 1.6 + Math.random() * 1.4,
            color: Math.random() > 0.35 ? '214,232,128' : '154,224,180', seed: Math.random() * 10, alpha: 0.9
          });
          break;
        case 'sparkle':
          addParticle(game, {
            kind: 'sparkle', x, y, life: 1 + Math.random() * 1.6, size: 1 + Math.random() * 1.8,
            color: em.color || '126,220,240', vy: -6 - Math.random() * 12, drag: 0.2
          });
          break;
        case 'leaf':
          addParticle(game, {
            kind: 'leaf', x: x + (Math.random() - 0.5) * 700, y: y + (Math.random() - 0.5) * 500,
            vx: -8 + Math.random() * 16, vy: 8 + Math.random() * 16, life: 6 + Math.random() * 5,
            size: 2.5 + Math.random() * 2.5, color: Math.random() > 0.5 ? '112,132,70' : '150,130,70',
            rot: Math.random() * TAU, spin: (Math.random() - 0.5) * 3, drag: 0.02
          });
          break;
        default:
          break;
      }
    }
  }
}

export function footstep(game, x, y, biome) {
  const color = biome === 1 ? '183,164,122' : biome === 4 ? '150,148,136' : '155,168,112';
  for (let i = 0; i < 3; i++) {
    addParticle(game, {
      kind: 'dust', x: x + (Math.random() - 0.5) * 12, y: y + 3 + Math.random() * 4,
      vx: (Math.random() - 0.5) * 24, vy: -6 - Math.random() * 12,
      life: 0.4 + Math.random() * 0.25, size: 2.5 + Math.random() * 3, color, drag: 3
    });
  }
}

export function updateEmittersForRenderer(game) {
  // Ambient emitters are updated in updateAmbient; this hook is kept for ordering.
  void game;
}

export function enemyDeathFx(game, e) {
  const count = e.isBoss ? 45 : 14;
  puff(game, e.x, e.y, count, e.type === 'gloom' ? '92,72,110' : '125,121,110', e.isBoss ? 2 : 1);
  debris(game, e.x, e.y, e.isBoss ? 28 : 8, e.type === 'gloom' ? '95,76,120' : '132,127,112', e.isBoss ? 1.8 : 1);
  sparks(game, e.x, e.y, e.isBoss ? 30 : 6, e.type === 'gloom' ? '196,142,235' : '255,196,110');
  addRing(game, e.x, e.y, 10, e.isBoss ? 190 : 48, e.isBoss ? '246,166,90' : '180,166,132', e.isBoss ? 0.9 : 0.45, e.isBoss ? 8 : 3);
}

export function randomOf(rng) {
  return rng();
}

export function leafColor() {
  return hash2(Math.random() * 1000 | 0, Math.random() * 1000 | 0, 5);
}

export function clampToView(game, x, y) {
  return { x: clamp(x, 0, game.viewport.w), y: clamp(y, 0, game.viewport.h) };
}

import { TAU, clamp, dist, range, mulberry32 } from './util.js';
import {
  addParticle, addRing, addTelegraph, addText, debris, enemyDeathFx, puff,
  sparks, spawnPickup
} from './game-fx.js';
import { PLAY, VILLAGE } from './world-data.js';

export const ENEMY_TYPES = {
  gloom: { r: 16, hp: 38, speed: 98, dmg: 10, aggro: 400, atkRange: 44, windup: 0.44, cooldown: 1.25, essence: 2, name: 'Gloomling' },
  wretch: { r: 23, hp: 108, speed: 74, dmg: 17, aggro: 430, atkRange: 56, windup: 0.62, cooldown: 1.75, essence: 4, name: 'Stone Wretch' },
  bat: { r: 13, hp: 26, speed: 160, dmg: 8, aggro: 440, atkRange: 38, windup: 0.3, cooldown: 0.9, essence: 2, name: 'Maw Bat' },
  warden: { r: 46, hp: 560, speed: 82, dmg: 26, aggro: 620, atkRange: 120, windup: 0.85, cooldown: 2.6, essence: 30, name: 'The Hollow Warden' }
};

let idCounter = 1;
const spawnRng = mulberry32(0x9a1f2c);

export function makeEnemy(game, type, x, y, zone) {
  const t = ENEMY_TYPES[type];
  return {
    id: idCounter++,
    type,
    name: t.name,
    x, y,
    r: t.r,
    hp: t.hp,
    maxHp: t.hp,
    speed: t.speed,
    dmg: t.dmg,
    aggroRange: t.aggro,
    atkRange: t.atkRange,
    windupMax: t.windup,
    cooldownMax: t.cooldown,
    essence: t.essence,
    home: { x, y },
    zone: zone || null,
    state: 'wander',
    aggro: false,
    aggroTimer: 0,
    windup: 0,
    cd: 0.5 + Math.random() * 1.4,
    dir: Math.random() * TAU,
    moving: false,
    walk: Math.random() * 10,
    hitFlash: 0,
    wanderTimer: Math.random() * 2,
    tx: x,
    ty: y,
    isBoss: type === 'warden',
    summonDone: false,
    dead: false,
    seed: Math.random() * 100,
    stuck: 0
  };
}

export function resetEnemies(game) {
  game.enemies = [];
  game.bossActive = false;
  game.bossKilled = false;
  game.zoneTimers = {};
  const boss = makeEnemy(game, 'warden', game.world.bossHome.x, game.world.bossHome.y, null);
  boss.state = 'idle';
  game.boss = boss;
  game.enemies.push(boss);
  for (const zone of game.world.zones) {
    game.zoneTimers[zone.id] = 0;
    for (let i = 0; i < zone.count; i++) spawnFromZone(game, zone);
  }
}

export function spawnFromZone(game, zone) {
  for (let attempt = 0; attempt < 40; attempt++) {
    const a = Math.random() * TAU;
    const rr = Math.sqrt(Math.random()) * zone.r;
    const x = clamp(zone.x + Math.cos(a) * rr, PLAY.x + 60, PLAY.x + PLAY.w - 60);
    const y = clamp(zone.y + Math.sin(a) * rr, PLAY.y + 60, PLAY.y + PLAY.h - 60);
    const type = zone.type;
    const t = ENEMY_TYPES[type];
    if (!game.world.canOccupy(x, y, t.r + 6)) continue;
    if (dist(x, y, game.player.x, game.player.y) < 360) continue;
    if (dist(x, y, VILLAGE.x, VILLAGE.y) < 520) continue;
    const e = makeEnemy(game, type, x, y, zone);
    game.enemies.push(e);
    addRing(game, x, y, 8, 42, '132,116,158', 0.6, 2);
    puff(game, x, y, 5, '90,80,105', 0.6);
    return e;
  }
  return null;
}

function moveTowards(game, e, tx, ty, speed, dt) {
  const dx = tx - e.x;
  const dy = ty - e.y;
  const len = Math.hypot(dx, dy);
  if (len < 1) { e.moving = false; return; }
  e.dir = Math.atan2(dy, dx);
  e.moving = true;
  const sp = speed;
  const res = game.world.resolveMove(e.x, e.y, e.r, (dx / len) * sp * dt, (dy / len) * sp * dt);
  if (Math.abs(res.x - e.x) + Math.abs(res.y - e.y) < 0.2) {
    e.stuck += dt;
    if (e.stuck > 0.5) {
      e.dir += 1.4 + Math.random();
      e.tx = e.x + Math.cos(e.dir) * 90;
      e.ty = e.y + Math.sin(e.dir) * 90;
      e.stuck = 0;
    }
  } else {
    e.stuck = 0;
  }
  e.x = res.x;
  e.y = res.y;
}

function startAttack(game, e) {
  e.windup = e.windupMax;
  e.cd = e.cooldownMax;
  if (e.isBoss) {
    addTelegraph(game, e.x, e.y + 10, 178, e.windupMax + 0.1, '214,92,60');
    game.audio.play('boss');
  } else {
    addTelegraph(game, e.x, e.y, e.atkRange + 18, e.windupMax, '204,92,70');
  }
}

function strike(game, e) {
  const p = game.player;
  const d = dist(e.x, e.y, p.x, p.y);
  if (e.isBoss) {
    const radius = 178;
    addRing(game, e.x, e.y + 8, 20, radius, '231,140,80', 0.55, 9);
    addRing(game, e.x, e.y + 8, 8, radius * 0.7, '255,205,130', 0.4, 5);
    debris(game, e.x, e.y + 6, 22, '148,138,116', 1.5);
    puff(game, e.x, e.y + 10, 18, '174,162,134', 1.5);
    game.shake = Math.max(game.shake, 14);
    game.audio.play('burst');
    if (d < radius + p.r) game.damagePlayer(e.dmg, e);
  } else {
    addRing(game, e.x, e.y, 6, e.atkRange + 22, '188,98,78', 0.32, 3);
    sparks(game, (e.x + p.x) / 2, (e.y + p.y) / 2, 5, '226,150,110');
    game.audio.play('hit');
    if (d < e.atkRange + p.r + 10) game.damagePlayer(e.dmg, e);
  }
}

function summonMinions(game, e) {
  for (let i = 0; i < 2; i++) {
    const a = Math.random() * TAU;
    const x = e.x + Math.cos(a) * 90;
    const y = e.y + Math.sin(a) * 90;
    const m = makeEnemy(game, 'gloom', x, y, null);
    m.aggro = true;
    m.aggroTimer = 10;
    m.home = { x, y };
    game.enemies.push(m);
    addRing(game, x, y, 4, 50, '170,120,210', 0.6, 3);
    puff(game, x, y, 8, '92,72,110', 0.9);
  }
  game.ui?.showToast('The Warden calls the dark to its side.', 'gold');
}

export function updateEnemies(game, dt) {
  const p = game.player;
  const others = game.enemies;

  for (const e of others) {
    if (e.dead) continue;
    e.hitFlash = Math.max(0, e.hitFlash - dt);
    e.aggroTimer = Math.max(0, e.aggroTimer - dt);
    e.walk += dt * (e.moving ? 7 : 2);
    e.cd = Math.max(0, e.cd - dt);

    if (e.isBoss) {
      const dp = dist(e.x, e.y, p.x, p.y);
      if (!game.bossActive && dp < 560) {
        game.bossActive = true;
        game.audio.play('boss');
        game.ui?.showToast('The Hollow Warden wakes.', 'gold');
        game.ui?.showBoss(true);
        game.shake = Math.max(game.shake, 8);
        addRing(game, e.x, e.y, 20, 240, '222,142,84', 0.9, 6);
      }
      if (!game.bossActive) {
        e.moving = false;
        continue;
      }
    }

    if (e.windup > 0) {
      e.moving = false;
      e.windup -= dt;
      if (e.windup <= 0) strike(game, e);
      continue;
    }

    const dp = dist(e.x, e.y, p.x, p.y);
    const leash = dist(e.x, e.y, e.home.x, e.home.y);
    const playerNearHome = dist(p.x, p.y, e.home.x, e.home.y) < 980;

    if (dp < e.aggroRange && playerNearHome) e.aggro = true;
    if (e.aggroTimer > 0) e.aggro = true;
    if (e.isBoss && game.bossActive) e.aggro = true;
    if (e.aggro && (leash > 1200 || dp > 1300) && !e.isBoss) {
      e.aggro = false;
      e.state = 'return';
    }

    if (e.aggro && !game.player.dead) {
      if (dp <= e.atkRange && e.cd <= 0) {
        startAttack(game, e);
        continue;
      }
      // Boss gets a burst of speed when winding up the distance.
      const sp = e.isBoss ? (dp > 220 ? e.speed * 1.25 : e.speed) : e.speed;
      moveTowards(game, e, p.x, p.y, sp, dt);
      if (e.isBoss && e.hp < e.maxHp * 0.5 && !e.summonDone) {
        e.summonDone = true;
        summonMinions(game, e);
      }
    } else {
      e.state = 'wander';
      e.wanderTimer -= dt;
      if (e.wanderTimer <= 0) {
        e.wanderTimer = 1.6 + Math.random() * 3;
        const a = Math.random() * TAU;
        const r = 40 + Math.random() * 110;
        e.tx = e.home.x + Math.cos(a) * r;
        e.ty = e.home.y + Math.sin(a) * r;
      }
      if (dist(e.x, e.y, e.tx, e.ty) > 12) moveTowards(game, e, e.tx, e.ty, e.speed * 0.32, dt);
      else e.moving = false;
    }

    // Soft separation so packs don't stack.
    for (const o of others) {
      if (o === e || o.dead) continue;
      const dx = e.x - o.x;
      const dy = e.y - o.y;
      const min = e.r + o.r;
      const d2 = dx * dx + dy * dy;
      if (d2 > 0.01 && d2 < min * min) {
        const d = Math.sqrt(d2);
        const push = (min - d) * 0.45;
        e.x += (dx / d) * push;
        e.y += (dy / d) * push;
      }
    }
  }

  game.enemies = game.enemies.filter((e) => !e.dead);
}

export function damageEnemy(game, e, dmg, knock = 0, dir = 0) {
  if (!e || e.dead) return;
  e.hp -= dmg;
  e.hitFlash = 0.18;
  e.aggro = true;
  e.aggroTimer = Math.max(e.aggroTimer, 5);
  addText(game, e.x + (Math.random() - 0.5) * 14, e.y - e.r - 18, Math.round(dmg), e.isBoss ? '#ffd08a' : '#f4e4c0', e.isBoss ? 19 : 14);
  sparks(game, e.x, e.y - e.r * 0.4, 4, e.type === 'gloom' ? '186,140,226' : '240,205,150');
  if (knock && !e.isBoss) {
    const res = game.world.resolveMove(e.x, e.y, e.r, Math.cos(dir) * knock, Math.sin(dir) * knock);
    e.x = res.x;
    e.y = res.y;
  }
  if (e.isBoss) {
    game.ui?.showBoss(true);
    game.shake = Math.max(game.shake, 3);
  }
  if (e.hp <= 0) killEnemy(game, e);
}

export function killEnemy(game, e) {
  if (e.dead) return;
  e.dead = true;
  enemyDeathFx(game, e);
  game.audio.play(e.isBoss ? 'victory' : 'enemyDie');
  game.onEnemyKilled(e);

  if (e.isBoss) {
    game.shake = Math.max(game.shake, 22);
    game.bossActive = false;
    for (let i = 0; i < 9; i++) spawnPickup(game, e.x, e.y, 'essence', 5, true);
    spawnPickup(game, e.x, e.y, 'heart', 40, false);
    game.ui?.showBoss(false);
  } else {
    const orbs = e.type === 'wretch' ? 2 + (Math.random() > 0.5 ? 1 : 0) : 1 + (Math.random() > 0.7 ? 1 : 0);
    for (let i = 0; i < orbs; i++) spawnPickup(game, e.x, e.y, 'essence', e.essence, true);
    const heartChance = e.type === 'wretch' ? 0.24 : e.type === 'bat' ? 0.1 : 0.16;
    if (Math.random() < heartChance) spawnPickup(game, e.x, e.y, 'heart', 18, true);
  }
}

export function updateSpawner(game, dt) {
  if (!game.world.zones) return;
  for (const zone of game.world.zones) {
    let alive = 0;
    for (const e of game.enemies) {
      if (!e.dead && e.zone && e.zone.id === zone.id) alive++;
    }
    if (alive >= zone.count) continue;
    game.zoneTimers[zone.id] = (game.zoneTimers[zone.id] || 0) - dt;
    if (game.zoneTimers[zone.id] <= 0) {
      game.zoneTimers[zone.id] = zone.respawn;
      spawnFromZone(game, zone);
    }
  }
}

import { TAU, clamp, lerp, dist, angleTo } from './util.js';
import { PLAYER_START, VILLAGE, FOREST, CAVE, PLAY } from './world-data.js';
import {
  initFx, puff, debris, sparks, addRing, addText, updateFx, updateAmbient,
  updatePickups, footstep, spawnPickup
} from './game-fx.js';
import {
  resetEnemies, updateEnemies, updateSpawner, damageEnemy
} from './game-enemies.js';

const SUBTITLES = {
  village: 'A quiet place, for now',
  forest: 'Old trees, older shadows',
  cave: 'Do not answer the knocking',
  pond: 'Where the sky rests',
  highlands: 'Above the green, the bare stone',
  fields: 'The valley feeds its people',
  valley: 'A mountain holds its breath'
};

function makePlayer() {
  return {
    x: PLAYER_START.x,
    y: PLAYER_START.y,
    r: 16,
    speed: 260,
    hp: 100,
    maxHp: 100,
    mana: 100,
    maxMana: 100,
    damage: 30,
    burstDamage: 40,
    essence: 0,
    facing: -Math.PI / 2,
    aimAngle: -Math.PI / 2,
    moving: false,
    walk: 0,
    throwCd: 0,
    burstCd: 0,
    invuln: 0,
    cast: 0,
    hurt: 0,
    manaFlash: 0,
    footTimer: 0,
    dead: false
  };
}

export class Game {
  constructor(world, audio) {
    this.world = world;
    this.audio = audio;
    this.ui = null;
    this.time = 0;
    this.playTime = 0;
    this.started = false;
    this.paused = false;
    this.finished = false;
    this.viewport = { w: window.innerWidth, h: window.innerHeight };
    this.zoom = 1;
    this.camera = { x: PLAYER_START.x, y: PLAYER_START.y };
    this.aim = { x: PLAYER_START.x + 100, y: PLAYER_START.y - 50 };
    this.aimMode = 'mouse';
    this.shake = 0;
    this.hurtFlash = 0;
    this.areaKey = 'village';
    this.areaTimer = 0;
    this.prompt = null;
    this.projectiles = [];
    this.bossActive = false;
    this.sheep = [];
    this.setViewport(this.viewport.w, this.viewport.h);
    this.newRun(false);
  }

  setViewport(w, h) {
    this.viewport.w = w;
    this.viewport.h = h;
    this.zoom = clamp(w / 720, 0.9, 1.24);
  }

  newRun(announce = true) {
    this.started = true;
    this.paused = false;
    this.dead = false;
    this.finished = false;
    this.player = makePlayer();
    this.quest = { stage: 0, kills: 0, target: 8, bossDead: false };
    this.stats = { kills: 0, deaths: 0, essence: 0, shrines: 0 };
    this.playTime = 0;
    this.projectiles = [];
    this.world.shrine.level = 0;
    this.world.bossActive = false;
    this.initWorldState();
    if (announce && this.ui) {
      this.ui.showArea('Hollowmere Village', SUBTITLES.village);
      this.ui.showToast('WASD to walk · hold LMB to hurl stones', 'gold');
    }
  }

  start() {
    if (this.started) {
      this.paused = false;
      return;
    }
    this.started = true;
    this.playTime = 0;
    this.camera.x = this.player.x;
    this.camera.y = this.player.y;
    if (this.ui) {
      this.ui.showArea('Hollowmere Village', SUBTITLES.village);
      this.ui.showToast('WASD to walk · hold LMB to hurl stones', 'gold');
    }
  }

  initWorldState() {
    initFx(this);
    this.bossActive = false;
    resetEnemies(this);
    this.projectiles = [];
    this.camera.x = this.player.x;
    this.camera.y = this.player.y;
    this.shake = 0;
    this.hurtFlash = 0;
    this.areaKey = null;
    this.areaTimer = 0;
    this.spawnAcc = 0;
    this.buildSheep();
    this.aim = { x: this.player.x + 120, y: this.player.y - 60 };
    this.prompt = null;
  }

  buildSheep() {
    this.sheep = [];
    const flocks = [
      { x: 3875, y: 3140, w: 260, h: 120, n: 4 },
      { x: 4320, y: 2410, w: 400, h: 400, n: 4 }
    ];
    for (const f of flocks) {
      for (let i = 0; i < f.n; i++) {
        this.sheep.push({
          x: f.x + Math.random() * f.w,
          y: f.y + Math.random() * f.h,
          tx: f.x + Math.random() * f.w,
          ty: f.y + Math.random() * f.h,
          timer: Math.random() * 4,
          walk: Math.random() * 10,
          dir: Math.random() * TAU,
          phase: Math.random() * 10,
          bounds: f
        });
      }
    }
  }

  respawn() {
    const p = this.player;
    this.dead = false;
    p.dead = false;
    p.hp = p.maxHp;
    p.mana = p.maxMana;
    p.invuln = 2.2;
    p.x = this.world.shrine.x + 58;
    p.y = this.world.shrine.y + 66;
    this.camera.x = p.x;
    this.camera.y = p.y;
    this.bossActive = false;
    if (this.boss) {
      this.boss.x = this.world.bossHome.x;
      this.boss.y = this.world.bossHome.y;
      this.boss.aggro = false;
      this.boss.windup = 0;
    }
    for (const e of this.enemies) {
      if (!e.isBoss) e.aggro = false;
    }
    this.hurtFlash = 0;
    this.shake = 0;
    this.audio.play('heal');
    this.ui?.hideDeath();
    this.ui?.showToast('The stone remembers you. Rise.', 'gold');
  }

  update(dt, input, active) {
    this.time += dt;
    const p = this.player;
    if (active) {
      this.playTime += dt;
      this.updatePlayer(dt, input);
      this.updateProjectiles(dt);
      updateEnemies(this, dt);
      updatePickups(this, dt);
      updateSpawner(this, dt);
      this.updateSheep(dt);
      this.updateArea(dt);
      this.updatePrompt();
      updateAmbient(this, dt);
      if (this.quest.stage === 3 && this.quest.bossDead) {
        this.setQuestStage(4);
        this.ui?.showToast('The Warden is dead. Return to Elder Rowan.', 'gold');
      }
      p.invuln = Math.max(0, p.invuln - dt);
      p.cast = Math.max(0, p.cast - dt);
      p.manaFlash = Math.max(0, p.manaFlash - dt);
      p.throwCd = Math.max(0, p.throwCd - dt);
      p.burstCd = Math.max(0, p.burstCd - dt);
      p.mana = Math.min(p.maxMana, p.mana + 9.5 * dt);
      p.hurt = Math.max(0, p.hurt - dt * 2);
      this.lastHurt = (this.lastHurt || 0) + dt;
      if (this.lastHurt > 7 && p.hp < p.maxHp && !p.dead) p.hp = Math.min(p.maxHp, p.hp + 1.4 * dt);
    } else {
      updateAmbient(this, dt);
    }
    updateFx(this, dt);
    this.updateCamera(dt);
    this.shake *= Math.exp(-7 * dt);
    this.hurtFlash = Math.max(0, this.hurtFlash - dt * 2.4);
    p.invuln = Math.max(0, p.invuln - dt * 0);
  }

  updatePlayer(dt, input) {
    const p = this.player;
    const move = input.getMove();
    p.moving = move.mag > 0.08;
    if (p.moving) {
      p.facing = Math.atan2(move.y, move.x);
      const sp = p.speed;
      const res = this.world.resolveMove(p.x, p.y, p.r, move.x * sp * dt, move.y * sp * dt);
      p.x = res.x;
      p.y = res.y;
      p.walk += dt * 9;
      p.footTimer -= dt;
      if (p.footTimer <= 0) {
        p.footTimer = 0.2;
        footstep(this, p.x, p.y, this.world.biomeAt(p.x, p.y));
        if (Math.random() > 0.6) this.audio.play('step');
      }
    }

    const aim = this.computeAim(input);
    this.aim = aim.point;
    this.aimMode = aim.mode;
    p.aimAngle = Math.atan2(aim.point.y - p.y, aim.point.x - p.x);

    if (input.consumeThrowQueue()) this.tryThrow(input);
    if (input.isThrowing() && input.aimMode() !== 'touch') this.tryThrow(input);
    if (input.consumePressed('Space') || input.consumeBurst()) this.castBurst();
    if (input.consumePressed('KeyE')) this.interact();
  }

  screenToWorld(sx, sy) {
    return {
      x: this.camera.x + (sx - this.viewport.w / 2) / this.zoom,
      y: this.camera.y + (sy - this.viewport.h / 2) / this.zoom
    };
  }

  nearestEnemy(x, y, maxDist = 1000) {
    let best = null;
    let bd = maxDist;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist(x, y, e.x, e.y);
      if (d < bd) { bd = d; best = e; }
    }
    return best;
  }

  bestInCone(px, py, dx, dy, maxDist, maxAngle) {
    let best = null;
    let bestScore = Infinity;
    const base = Math.atan2(dy, dx);
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist(px, py, e.x, e.y);
      if (d > maxDist || d < 10) continue;
      const a = Math.atan2(e.y - py, e.x - px);
      let da = Math.abs(a - base);
      if (da > Math.PI) da = TAU - da;
      if (da > maxAngle) continue;
      const score = d * (1 + da / (maxAngle + 0.001) * 1.6);
      if (score < bestScore) { bestScore = score; best = e; }
    }
    return best;
  }

  computeAim(input) {
    const p = this.player;
    const useTouch = input.touchMode && !input.mouse.seen;
    if (useTouch) {
      let dx = input.lastAimDir.x;
      let dy = input.lastAimDir.y;
      if (input.aimTouch && input.aimTouch.moved) {
        dx = input.aimTouch.x - input.aimTouch.sx;
        dy = input.aimTouch.y - input.aimTouch.sy;
        const l = Math.hypot(dx, dy) || 1;
        dx /= l; dy /= l;
      }
      if (input.touchThrowHeld) {
        const near = this.nearestEnemy(p.x, p.y, 900);
        if (near) return { point: { x: near.x, y: near.y }, mode: 'auto' };
        return {
          point: { x: p.x + Math.cos(p.aimAngle || 0) * 420, y: p.y + Math.sin(p.aimAngle || 0) * 420 },
          mode: 'auto'
        };
      }
      const target = this.bestInCone(p.x, p.y, dx, dy, 820, 0.38);
      if (target) return { point: { x: target.x, y: target.y }, mode: 'touch' };
      return { point: { x: p.x + dx * 520, y: p.y + dy * 520 }, mode: 'touch', dir: { x: dx, y: dy } };
    }

    if (input.touchThrowHeld) {
      const near = this.nearestEnemy(p.x, p.y, 900);
      if (near) return { point: { x: near.x, y: near.y }, mode: 'auto' };
      return { point: { x: p.x + Math.cos(p.facing) * 420, y: p.y + Math.sin(p.facing) * 420 }, mode: 'auto' };
    }

    const w = this.screenToWorld(input.mouse.x, input.mouse.y);
    let point = w;
    const near = this.nearestEnemy(w.x, w.y, 86);
    if (near) point = { x: near.x, y: near.y };
    return { point, mode: 'mouse' };
  }

  tryThrow(input) {
    const p = this.player;
    if (p.throwCd > 0 || p.dead || this.finished) return;
    if (p.mana < 9) {
      p.manaFlash = 0.6;
      p.throwCd = 0.3;
      this.audio.play('invalid');
      return;
    }
    const aim = this.computeAim(input).point;
    let tx = aim.x;
    let ty = aim.y;
    if (dist(p.x, p.y, tx, ty) < 45) {
      tx = p.x + Math.cos(p.aimAngle) * 180;
      ty = p.y + Math.sin(p.aimAngle) * 180;
    }
    p.mana -= 9;
    p.throwCd = 0.34;
    p.cast = 0.2;
    const sx = p.x + Math.cos(p.aimAngle) * 20;
    const sy = p.y - 10 + Math.sin(p.aimAngle) * 16;
    const d = dist(sx, sy, tx, ty);
    const dur = clamp(d / 920, 0.16, 0.75);
    this.projectiles.push({
      sx, sy, tx, ty, x: sx, y: sy,
      t: 0, dur,
      arc: clamp(d * 0.24, 30, 150),
      dmg: p.damage,
      radius: 64,
      rot: Math.random() * TAU,
      spin: (Math.random() - 0.5) * 18
    });
    this.audio.play('throw');
    puff(this, sx, sy, 3, '166,158,128', 0.5);
    sparks(this, sx, sy, 3, '196,214,150');
  }

  castBurst() {
    const p = this.player;
    if (p.dead || this.finished) return;
    if (p.burstCd > 0) {
      this.audio.play('invalid');
      return;
    }
    if (p.mana < 28) {
      p.manaFlash = 0.7;
      this.audio.play('invalid');
      this.ui?.showToast('Not enough mana.', 'gold');
      return;
    }
    p.mana -= 28;
    p.burstCd = 4.5;
    p.cast = 0.35;
    this.shake = Math.max(this.shake, 11);
    this.audio.play('burst');
    addRing(this, p.x, p.y, 26, 190, '190,220,150', 0.55, 8);
    addRing(this, p.x, p.y, 10, 120, '255,226,160', 0.35, 4);
    debris(this, p.x, p.y + 4, 24, '156,146,118', 1.5);
    puff(this, p.x, p.y + 8, 18, '178,164,128', 1.4);
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist(p.x, p.y, e.x, e.y);
      if (d < 195) {
        const falloff = 1 - (d / 195) * 0.45;
        damageEnemy(this, e, p.burstDamage * falloff, 46, Math.atan2(e.y - p.y, e.x - p.x));
        e.aggro = true;
        e.aggroTimer = 5;
      }
    }
  }

  updateProjectiles(dt) {
    for (const pr of this.projectiles) {
      if (pr.done) continue;
      pr.t += dt;
      pr.rot += pr.spin * dt;
      const k = clamp(pr.t / pr.dur, 0, 1);
      const ease = k;
      pr.x = lerp(pr.sx, pr.tx, ease);
      pr.y = lerp(pr.sy, pr.ty, ease);
      if (k > 0.08 && k < 0.97) {
        let hit = null;
        for (const e of this.enemies) {
          if (e.dead) continue;
          if (dist(pr.x, pr.y, e.x, e.y) < e.r + 15) { hit = e; break; }
        }
        if (hit) {
          this.detonate(pr, hit.x, hit.y);
          continue;
        }
      }
      if (k >= 1) this.detonate(pr, pr.tx, pr.ty);
    }
    this.projectiles = this.projectiles.filter((p) => !p.done);
  }

  detonate(pr, x, y) {
    pr.done = true;
    const p = this.player;
    const water = this.world.isWater(x, y);
    if (water) {
      for (let i = 0; i < 14; i++) {
        addRing(this, x, y, 2, 20 + Math.random() * 34, '158,208,212', 0.4, 2);
      }
      puff(this, x, y, 10, '176,216,218', 0.9);
      this.audio.play('impact');
    } else {
      addRing(this, x, y, 6, pr.radius, '214,190,140', 0.42, 3);
      debris(this, x, y, 12, '148,140,118', 1);
      puff(this, x, y, 10, '184,170,136', 0.9);
      this.audio.play('impact');
    }
    this.shake = Math.max(this.shake, clamp(7 - dist(x, y, p.x, p.y) / 140, 1.5, 7));
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = dist(x, y, e.x, e.y);
      if (d < pr.radius + e.r) {
        const falloff = 1 - (d / (pr.radius + e.r)) * 0.45;
        damageEnemy(this, e, pr.dmg * falloff, 26, Math.atan2(e.y - y, e.x - x));
        e.aggro = true;
        e.aggroTimer = 5;
      }
    }
  }

  damagePlayer(dmg, source) {
    const p = this.player;
    if (p.dead || p.invuln > 0 || this.finished) return;
    p.hp -= dmg;
    p.invuln = 0.92;
    p.hurt = 1;
    this.hurtFlash = 1;
    this.shake = Math.max(this.shake, 10);
    this.lastHurt = 0;
    this.audio.play('hurt');
    if (navigator.vibrate) { try { navigator.vibrate(45); } catch {} }
    addText(this, p.x, p.y - 38, '-' + Math.round(dmg), '#ff9b86', 16);
    puff(this, p.x, p.y, 7, '170,110,96', 0.8);
    if (source) {
      const a = Math.atan2(p.y - source.y, p.x - source.x);
      const res = this.world.resolveMove(p.x, p.y, p.r, Math.cos(a) * 26, Math.sin(a) * 26);
      p.x = res.x;
      p.y = res.y;
    }
    if (p.hp <= 0) {
      p.hp = 0;
      p.dead = true;
      this.dead = true;
      this.stats.deaths++;
      this.audio.play('enemyDie');
      this.ui?.showDeath();
    }
  }

  updatePrompt() {
    const p = this.player;
    if (p.dead || this.finished || this.dead) { this.prompt = null; return; }
    const candidates = [];
    const dElder = dist(p.x, p.y, this.world.elder.x, this.world.elder.y);
    if (dElder < 118) candidates.push({ type: 'elder', d: dElder, x: this.world.elder.x, y: this.world.elder.y, label: this.quest.stage === 0 ? 'Speak with Elder Rowan' : 'Talk to Elder Rowan' });
    const dShrine = dist(p.x, p.y, this.world.shrine.x, this.world.shrine.y);
    if (dShrine < 105) {
      const cost = 25 + this.stats.shrines * 20;
      candidates.push({
        type: 'shrine', d: dShrine, x: this.world.shrine.x, y: this.world.shrine.y,
        label: p.essence >= cost ? `Infuse the shrine (${cost} essence)` : `Shrine asks for ${cost} essence`
      });
    }
    for (const s of this.world.signs) {
      const d = dist(p.x, p.y, s.x, s.y);
      if (d < 88) candidates.push({ type: 'sign', d, x: s.x, y: s.y, sign: s, label: 'Read the signpost' });
    }
    candidates.sort((a, b) => a.d - b.d);
    this.prompt = candidates[0] || null;
  }

  interact() {
    if (this.ui?.dialogueOpen) return;
    const target = this.prompt;
    if (!target) return;
    if (target.type === 'elder') this.talkToElder();
    else if (target.type === 'shrine') this.useShrine();
    else if (target.type === 'sign') {
      this.audio.play('pickup');
      this.ui?.showDialogue({
        name: target.sign.type === 'cave' ? 'Weathered Warning' : 'Village Signpost',
        portrait: '!',
        lines: target.sign.text.split('\n')
      });
    }
  }

  talkToElder() {
    const q = this.quest;
    this.audio.play('pickup');
    if (q.stage === 0) {
      this.ui?.showDialogue({
        name: 'Elder Rowan',
        portrait: 'R',
        lines: [
          'You came, earth-child. Good. The valley has been restless since the moon turned thin.',
          'Gloomlings creep out of the Whisperwood. Eight have been seen circling the old stones. Take your staff and thin them.',
          'Hurl the mountain\u2019s bones. Return when the woods are quiet.'
        ],
        onDone: () => {
          this.quest.stage = 1;
          this.quest.kills = 0;
          this.audio.play('quest');
          this.ui?.showToast('New task — Thin the gloom in the Whisperwood.', 'gold');
        }
      });
    } else if (q.stage === 1) {
      this.ui?.showDialogue({
        name: 'Elder Rowan',
        portrait: 'R',
        lines: [
          `The gloom still gathers. ${this.quest.kills} of eight have fallen. The stone remembers each one.`,
          'The Whisperwood lies west, across the bridge. Do not let them circle behind you.'
        ]
      });
    } else if (q.stage === 2) {
      this.ui?.showDialogue({
        name: 'Elder Rowan',
        portrait: 'R',
        lines: [
          'The woods breathe again. You have the mountain\u2019s favour — take it. Your well of power deepens.',
          'But something below has noticed you. The Hollow Warden stirs at the Maw, north of the village.',
          'Go to the cave mouth. End it before it climbs into the valley. I will keep the fire lit.'
        ],
        onDone: () => {
          const p = this.player;
          p.maxMana += 20;
          p.mana = p.maxMana;
          p.hp = Math.min(p.maxHp, p.hp + 30);
          this.audio.play('heal');
          this.audio.play('quest');
          if (this.quest.bossDead) {
            this.quest.stage = 4;
            this.ui?.showToast('The Warden already lies dead. Return to Elder Rowan.', 'gold');
          } else {
            this.quest.stage = 3;
            this.ui?.showToast('New task — Slay the Hollow Warden at the Maw.', 'gold');
          }
        }
      });
    } else if (q.stage === 3) {
      this.ui?.showDialogue({
        name: 'Elder Rowan',
        portrait: 'R',
        lines: [
          'The Warden waits in the dark at the back of the Maw. Its fists are the size of doors.',
          'Strike from range. Move when the ground begins to glow. The mountain favours the patient.'
        ]
      });
    } else if (q.stage === 4) {
      this.ui?.showDialogue({
        name: 'Elder Rowan',
        portrait: 'R',
        lines: [
          'It is done. The knocking under the mountain has stopped.',
          'The valley will remember this. Not with a statue — with quiet mornings. That is better.',
          'Rest now, earth-child. The stones are yours to walk among.'
        ],
        onDone: () => {
          this.quest.stage = 5;
          this.finished = true;
          this.audio.play('victory');
          this.ui?.showVictory(this.stats, this.playTime, this.player.essence);
        }
      });
    } else {
      this.ui?.showDialogue({
        name: 'Elder Rowan',
        portrait: 'R',
        lines: ['The fire is warm and the valley is quiet. Stay as long as you like, earth-child.']
      });
    }
  }

  useShrine() {
    const cost = 25 + this.stats.shrines * 20;
    const p = this.player;
    if (p.essence < cost) {
      this.audio.play('invalid');
      this.ui?.showToast(`The shrine is thirsty. It asks for ${cost} earth essence.`, 'gold');
      return;
    }
    p.essence -= cost;
    this.stats.shrines++;
    this.world.shrine.level = this.stats.shrines;
    p.maxHp += 10;
    p.damage += 4;
    p.hp = Math.min(p.maxHp, p.hp + 30);
    p.mana = p.maxMana;
    this.audio.play('heal');
    addRing(this, this.world.shrine.x, this.world.shrine.y, 12, 130, '150,236,158', 0.8, 5);
    sparks(this, this.world.shrine.x, this.world.shrine.y - 30, 22, '158,238,170');
    this.ui?.showToast('The stone answers. +10 life, +4 stone damage.', 'gold');
    addText(this, p.x, p.y - 40, 'The stone answers', '#b8ecc0', 15);
  }

  onEnemyKilled(e) {
    this.stats.kills++;
    if (e.isBoss) {
      this.quest.bossDead = true;
      this.bossActive = false;
      this.audio.play('quest');
      this.ui?.showToast('The Hollow Warden falls. The valley exhales.', 'gold');
      if (this.quest.stage === 3) this.setQuestStage(4);
      return;
    }
    if (this.quest.stage === 1) {
      this.quest.kills++;
      if (this.quest.kills >= this.quest.target) {
        this.setQuestStage(2);
        this.audio.play('quest');
        this.ui?.showToast('The gloom thins. Return to Elder Rowan.', 'gold');
      }
    }
  }

  setQuestStage(stage) {
    this.quest.stage = stage;
  }

  initWorldStateDone() {}

  updateCamera(dt) {
    const p = this.player;
    const halfW = this.viewport.w / (2 * this.zoom);
    const halfH = this.viewport.h / (2 * this.zoom);
    const leadX = clamp((this.aim.x - p.x) * 0.12, -80, 80);
    const leadY = clamp((this.aim.y - p.y) * 0.12, -60, 60);
    let tx = p.x + leadX;
    let ty = p.y + leadY;
    if (halfW * 2 >= this.world.constructor ? false : false) { /* noop */ }
    tx = clamp(tx, halfW, Math.max(halfW, 5600 - halfW));
    ty = clamp(ty, halfH, Math.max(halfH, 4200 - halfH));
    const k = 1 - Math.exp(-7 * dt);
    this.camera.x = lerp(this.camera.x, tx, k);
    this.camera.y = lerp(this.camera.y, ty, k);
  }

  updateArea(dt) {
    this.areaTimer -= dt;
    if (this.areaTimer > 0) return;
    this.areaTimer = 0.55;
    const area = this.world.areaAt(this.player.x, this.player.y);
    if (area.key !== this.areaKey) {
      this.areaKey = area.key;
      if (area.key !== 'valley') {
        this.ui?.showArea(area.name, SUBTITLES[area.key] || '');
      }
    }
  }

  updateSheep(dt) {
    for (const s of this.sheep) {
      s.timer -= dt;
      s.walk += dt * (s.moving ? 6 : 2);
      if (s.timer <= 0) {
        s.timer = 2 + Math.random() * 5;
        const b = s.bounds;
        s.tx = b.x + Math.random() * b.w;
        s.ty = b.y + Math.random() * b.h;
      }
      const d = dist(s.x, s.y, s.tx, s.ty);
      s.moving = d > 8;
      if (s.moving) {
        const a = Math.atan2(s.ty - s.y, s.tx - s.x);
        s.dir = a;
        s.x += Math.cos(a) * 22 * dt;
        s.y += Math.sin(a) * 22 * dt;
      }
    }
  }

  // --------------------------------------------------------------- quest UI
  questInfo() {
    const q = this.quest;
    if (q.stage === 0) return { title: 'A Valley Unsettled', objective: 'Speak with Elder Rowan by the village well.' };
    if (q.stage === 1) return { title: 'Stone and Shadow', objective: `Thin the gloom in the Whisperwood — <b>${q.kills}/${q.target}</b> corrupted slain.` };
    if (q.stage === 2) return { title: 'Stone and Shadow', objective: 'Return to Elder Rowan at the village well.' };
    if (q.stage === 3) return { title: 'The Hollow Below', objective: 'Slay the Hollow Warden at the Maw, north of the village.' };
    if (q.stage === 4) return { title: 'The Hollow Below', objective: 'Return to Elder Rowan in the village.' };
    return { title: 'The Valley Breathes', objective: 'The valley is safe. Wander, or speak with Rowan.' };
  }

  objective() {
    const q = this.quest;
    if (q.stage === 0 || q.stage === 2 || q.stage === 4) return { x: this.world.elder.x, y: this.world.elder.y, label: 'Elder Rowan' };
    if (q.stage === 1) {
      const e = this.nearestEnemy(this.player.x, this.player.y, 1400);
      if (e) return { x: e.x, y: e.y, label: 'Gloom' };
      return { x: FOREST.x, y: FOREST.y, label: 'The Whisperwood' };
    }
    if (q.stage === 3) return { x: this.world.bossHome.x, y: this.world.bossHome.y, label: 'The Maw' };
    return null;
  }

  bossInfo() {
    if (!this.boss || this.boss.dead) return null;
    if (!this.bossActive) return null;
    return { hp: Math.max(0, this.boss.hp), maxHp: this.boss.maxHp, name: 'THE HOLLOW WARDEN' };
  }

  promptForUi() {
    return this.prompt ? { label: this.prompt.label, type: this.prompt.type } : null;
  }
}

import { clamp, formatTime } from './util.js';
import { VILLAGE, CAVE, FOREST, POND } from './world-data.js';

export class UI {
  constructor(game) {
    this.game = game;
    game.ui = this;
    this.el = {
      hud: document.getElementById('hud'),
      title: document.getElementById('title-screen'),
      hpFill: document.getElementById('hp-fill'),
      hpText: document.getElementById('hp-text'),
      mpFill: document.getElementById('mp-fill'),
      mpText: document.getElementById('mp-text'),
      questTitle: document.getElementById('quest-title'),
      questObjective: document.getElementById('quest-objective'),
      essence: document.getElementById('essence'),
      minimap: document.getElementById('minimap'),
      prompt: document.getElementById('interact'),
      promptText: document.getElementById('interact-text'),
      bossBar: document.getElementById('boss-bar'),
      bossFill: document.getElementById('boss-fill'),
      bossName: document.querySelector('.boss-name'),
      toast: document.getElementById('toast'),
      areaLabel: document.getElementById('area-label'),
      areaName: document.getElementById('area-name'),
      dialogue: document.getElementById('dialogue'),
      dlgName: document.getElementById('dlg-name'),
      dlgText: document.getElementById('dlg-text'),
      dlgPortrait: document.getElementById('dlg-portrait'),
      death: document.getElementById('death-screen'),
      victory: document.getElementById('victory-screen'),
      victoryStats: document.getElementById('victory-stats'),
      victoryText: document.getElementById('victory-text'),
      pause: document.getElementById('pause-screen'),
      mute: document.getElementById('btn-mute'),
      pauseBtn: document.getElementById('btn-pause'),
      burstBtn: document.getElementById('btn-burst'),
      throwBtn: document.getElementById('btn-throw'),
      loading: document.getElementById('loading')
    };
    this.toastTimer = 0;
    this.areaTimer = 0;
    this.dialogue = null;
    this.lastQuest = '';
    this.minimapAcc = 0;
    this.bossVisible = false;

    const mm = this.el.minimap;
    if (mm) { mm.width = 400; mm.height = 300; }
    this.mm = mm ? mm.getContext('2d') : null;

    this.el.dialogue?.addEventListener('click', () => this.advanceDialogue());
  }

  hideLoading() {
    const l = this.el.loading;
    if (!l) return;
    l.classList.add('out');
    setTimeout(() => l.classList.add('hidden'), 520);
  }

  showHud() {
    this.el.hud?.classList.remove('hidden');
  }

  hideTitle() {
    this.el.title?.classList.add('hidden');
  }

  startPresentation() {
    this.showHud();
    this.hideTitle();
  }

  showToast(text, kind = '') {
    const t = this.el.toast;
    if (!t) return;
    t.textContent = text;
    t.className = 'toast show ' + (kind || '');
    this.toastTimer = kind === 'gold' ? 4 : 3.2;
  }

  showArea(name, subtitle = '') {
    const a = this.el.areaLabel;
    const n = this.el.areaName;
    if (!a || !n) return;
    n.innerHTML = `${name}${subtitle ? `<small>${subtitle}</small>` : ''}`;
    a.classList.add('show');
    this.areaTimer = 3.1;
  }

  showDialogue({ name, lines, portrait = 'R', onDone = null }) {
    this.dialogue = { name, lines, index: 0, onDone, shown: 0, full: lines[0] || '', finished: false };
    const d = this.el.dialogue;
    if (!d) return;
    d.classList.remove('hidden');
    this.el.dlgName.textContent = name;
    this.el.dlgPortrait.textContent = portrait;
    this.el.dlgText.textContent = '';
    this.dialogueOpen = true;
  }

  get dialogueOpen() {
    return !!this.dialogue;
  }

  advanceDialogue() {
    const d = this.dialogue;
    if (!d) return;
    if (d.shown < d.full.length) {
      d.shown = d.full.length;
      this.el.dlgText.textContent = d.full;
      return;
    }
    d.index++;
    if (d.index >= d.lines.length) {
      this.dialogue = null;
      this.el.dialogue?.classList.add('hidden');
      const cb = d.onDone;
      if (cb) cb();
      return;
    }
    d.full = d.lines[d.index];
    d.shown = 0;
    this.el.dlgText.textContent = '';
  }

  update(dt) {
    if (this.dialogue) {
      const d = this.dialogue;
      if (d.shown < d.full.length) {
        d.shown = Math.min(d.full.length, d.shown + dt * 58);
        this.el.dlgText.textContent = d.full.slice(0, Math.floor(d.shown));
      } else {
        this.el.dlgText.textContent = d.full;
      }
    }
    if (this.toastTimer > 0) {
      this.toastTimer -= dt;
      if (this.toastTimer <= 0) this.el.toast?.classList.remove('show');
    }
    if (this.areaTimer > 0) {
      this.areaTimer -= dt;
      if (this.areaTimer <= 0) this.el.areaLabel?.classList.remove('show');
    }
  }

  sync(game) {
    const p = game.player;
    if (!p) return;
    const hpPct = clamp((p.hp / p.maxHp) * 100, 0, 100);
    const mpPct = clamp((p.mana / p.maxMana) * 100, 0, 100);
    if (this.el.hpFill) this.el.hpFill.style.width = hpPct + '%';
    if (this.el.hpText) this.el.hpText.textContent = `${Math.ceil(p.hp)} / ${Math.round(p.maxHp)}`;
    if (this.el.mpFill) this.el.mpFill.style.width = mpPct + '%';
    if (this.el.mpText) this.el.mpText.textContent = `${Math.ceil(p.mana)} / ${Math.round(p.maxMana)}`;
    if (this.el.essence) this.el.essence.textContent = p.essence;

    const info = game.questInfo();
    const key = info.title + '|' + info.objective;
    if (key !== this.lastQuest) {
      this.lastQuest = key;
      if (this.el.questTitle) this.el.questTitle.textContent = info.title;
      if (this.el.questObjective) this.el.questObjective.innerHTML = info.objective;
    }

    const prompt = game.promptForUi();
    const showPrompt = !!prompt && !this.dialogue && !game.dead && !game.finished && !game.paused;
    if (this.el.prompt) {
      this.el.prompt.classList.toggle('hidden', !showPrompt);
      if (showPrompt) {
        this.el.promptText.textContent = prompt.label;
      }
    }

    const boss = game.bossInfo();
    if (boss) {
      this.bossVisible = true;
      this.el.bossBar?.classList.remove('hidden');
      if (this.el.bossFill) this.el.bossFill.style.width = clamp(boss.hp / boss.maxHp * 100, 0, 100) + '%';
      if (this.el.bossName) this.el.bossName.textContent = boss.name;
    } else if (this.bossVisible) {
      this.bossVisible = false;
      this.el.bossBar?.classList.add('hidden');
    }

    if (this.el.burstBtn) {
      this.el.burstBtn.classList.toggle('cooldown', p.burstCd > 0.05);
    }
    if (this.el.throwBtn) {
      this.el.throwBtn.classList.toggle('cooldown', p.mana < 9);
    }

    this.minimapAcc += 1;
    if (this.minimapAcc >= 2) {
      this.minimapAcc = 0;
      this.drawMinimap(game);
    }
  }

  drawMinimap(game) {
    const ctx = this.mm;
    if (!ctx) return;
    const W = 400, H = 300;
    const sx = W / 5600;
    const sy = H / 4200;
    ctx.clearRect(0, 0, W, H);
    ctx.drawImage(game.world.minimapBase, 0, 0, W, H);
    // Soft vignette.
    const vg = ctx.createRadialGradient(W / 2, H / 2, 90, W / 2, H / 2, 250);
    vg.addColorStop(0, 'rgba(0,0,0,0)');
    vg.addColorStop(1, 'rgba(4,8,5,0.55)');
    ctx.fillStyle = vg;
    ctx.fillRect(0, 0, W, H);

    // Landmarks.
    const mark = (x, y, color, r = 4) => {
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(x * sx, y * sy, r, 0, Math.PI * 2);
      ctx.fill();
    };
    mark(VILLAGE.x, VILLAGE.y, 'rgba(238,204,140,0.9)', 5);
    mark(CAVE.x, CAVE.y, 'rgba(116,186,206,0.9)', 4.5);
    mark(FOREST.x, FOREST.y, 'rgba(108,150,92,0.85)', 5);
    mark(POND.x, POND.y, 'rgba(101,158,166,0.8)', 3.5);

    // Enemies.
    for (const e of game.enemies) {
      if (e.dead) continue;
      if (e.isBoss) {
        mark(e.x, e.y, 'rgba(238,138,70,0.95)', 5);
      } else {
        ctx.fillStyle = e.type === 'gloom' ? 'rgba(186,128,214,0.85)' : e.type === 'bat' ? 'rgba(170,140,214,0.8)' : 'rgba(208,154,104,0.85)';
        ctx.beginPath();
        ctx.arc(e.x * sx, e.y * sy, 2.2, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    // Objective diamond.
    const obj = game.objective();
    if (obj) {
      const ox = obj.x * sx;
      const oy = obj.y * sy;
      const pulse = 0.6 + Math.sin(game.time * 3) * 0.3;
      ctx.save();
      ctx.translate(ox, oy);
      ctx.rotate(Math.PI / 4);
      ctx.fillStyle = `rgba(246,206,124,${pulse})`;
      ctx.fillRect(-5, -5, 10, 10);
      ctx.strokeStyle = 'rgba(36,28,16,0.8)';
      ctx.lineWidth = 1.5;
      ctx.strokeRect(-5, -5, 10, 10);
      ctx.restore();
    }

    // Player arrow.
    const px = game.player.x * sx;
    const py = game.player.y * sy;
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(game.player.facing + Math.PI / 2);
    ctx.fillStyle = '#f8e7bd';
    ctx.beginPath();
    ctx.moveTo(0, -7);
    ctx.lineTo(5, 5);
    ctx.lineTo(0, 2);
    ctx.lineTo(-5, 5);
    ctx.closePath();
    ctx.fill();
    ctx.strokeStyle = 'rgba(30,24,14,0.8)';
    ctx.lineWidth = 1;
    ctx.stroke();
    ctx.restore();

    // Compass letter.
    ctx.fillStyle = 'rgba(239,213,158,0.9)';
    ctx.font = '600 13px system-ui, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('N', W - 18, 20);
  }

  showDeath() {
    this.el.death?.classList.remove('hidden');
    this.el.prompt?.classList.add('hidden');
  }

  hideDeath() {
    this.el.death?.classList.add('hidden');
  }

  showVictory(stats, playTime, essence) {
    this.el.victory?.classList.remove('hidden');
    if (this.el.victoryStats) {
      this.el.victoryStats.innerHTML = `
        <div><b>${stats.kills}</b><span>creatures felled</span></div>
        <div><b>${formatTime(playTime)}</b><span>time in the valley</span></div>
        <div><b>${essence}</b><span>earth essence</span></div>
        <div><b>${stats.shrines}</b><span>shrine blessings</span></div>`;
    }
  }

  hideVictory() {
    this.el.victory?.classList.add('hidden');
  }

  setPaused(paused) {
    this.el.pause?.classList.toggle('hidden', !paused);
    if (paused) this.el.prompt?.classList.add('hidden');
  }

  setMuted(muted) {
    if (!this.el.mute) return;
    this.el.mute.classList.toggle('muted', muted);
    const span = this.el.mute.querySelector('.sound-on');
    if (span) span.textContent = muted ? '✕' : '♪';
    this.el.mute.setAttribute('aria-label', muted ? 'Unmute sound' : 'Mute sound');
  }
}

